    pageLangSec4Desc: 'Semua teks UI digabungkan langsung ke dalam aplikasi, artinya Anda tidak memerlukan akses internet untuk berganti bahasa.',
    pageLangSec5Title: 'Peralihan yang Mulus',
    pageLangSec5Desc: 'Ubah bahasa secara instan tanpa memuat ulang aplikasi.',
    pageLangSec6Title: 'Siap Memulai?',
    pageLangSec6Desc: 'Pilih bahasa pilihan Anda dan nikmati alat dokumen offline tercepat di web.',
    footerUseCases: 'Kasus Penggunaan',
    pageUseCasesHero: 'Dibangun untuk Setiap Profesi',
    pageUseCasesHeroSub: 'Dari lingkungan hukum yang ketat hingga agensi kreatif, temukan alasan para profesional memercayai arsitektur pemrosesan sisi klien kami.',
    pageUseCasesBadge: 'Solusi Industri',
    pageUseCasesSec2Title: 'Firma Hukum & Hukum',
    pageUseCasesSec2Desc: 'Pengacara menangani NDA, kontrak, dan pengajuan pengadilan yang sangat rahasia. Mengunggah dokumen-dokumen ini ke API cloud acak merupakan tanggung jawab besar. Dengan HandleMyFile, tim hukum dapat menyunting, menggabungkan, dan membagi file kasus PDF sepenuhnya secara offline, memastikan kerahasiaan klien sepenuhnya.',
    pageUseCasesSec3Title: 'Sumber Daya Manusia (SDM)',
    pageUseCasesSec3Desc: 'Departemen SDM menangani PII (Informasi Identifikasi Pribadi) setiap hari. Memindai ID, menangani spreadsheet penggajian, dan mengelola surat penawaran memerlukan kepatuhan GDPR/CCPA yang ketat. HandleMyFile memungkinkan profesional HR mengelola file-file ini tanpa melanggar kebijakan keamanan TI internal.',
    pageUseCasesSec4Title: 'Pelajar & Pendidikan',
    pageUseCasesSec4Desc: 'Siswa tidak perlu membayar $20/bulan hanya untuk menggabungkan tugas proyek kelompok mereka atau mengompresi presentasi agar sesuai dengan batas unggah portal universitas sebesar 5MB. HandleMyFile menyediakan akses tak terbatas ke alat premium secara gratis, tanpa batasan ukuran file.',
    pageUseCasesSec5Title: 'Real Estat & Agen',
    pageUseCasesSec5Desc: 'Agen real estat menangani brosur properti berukuran besar yang dikemas dengan gambar beresolusi tinggi yang terlalu besar untuk dikirim melalui email ke klien. Mereka juga perlu dengan cepat menandai rencana properti dan menandatangani perjanjian sewa. HandleMyFile menangani file berukuran 100MB+ secara instan.',
    pageUseCasesSec6Title: 'Temukan Kasus Penggunaan Anda Sendiri',
    pageUseCasesSec6Desc: 'Apa pun industri Anda, jika Anda bekerja dengan dokumen, HandleMyFile adalah cara teraman dan tercepat untuk menyelesaikan pekerjaan. Coba rangkaian lengkap 20+ alat kami hari ini.',
    footerCompare: 'Membandingkan',
    pageCompareHero: 'HandleMyFile vs Yang Lainnya',
    pageCompareHeroSub: 'Bosan menunggu file diunggah? Frustrasi dengan batas file 5MB? Temukan alasan para profesional beralih ke alat dokumen sisi klien.',
    pageCompareBadge: 'Alternatif Cerdas',
    pageCompareSec2Title: 'Perbandingan Fitur',
    pageCompareSec3Title: 'Berhenti Menunggu di Bilah Kemajuan',
    pageAboutSec1Title: 'Kisah Asal Usul',
    pageAboutSec1Desc: 'Kami frustrasi dengan paywall dan kebocoran privasi yang terus-menerus terjadi pada alat dokumen online tradisional. Mengunggah file sensitif ke server acak pada dasarnya terasa salah. Kami membuat HandleMyFile untuk membuktikan bahwa alat tingkat perusahaan bisa gratis, cepat, dan sepenuhnya aman.',
    pageAboutSec2Title: 'Tumpukan Teknologi',
    pageAboutSec2Desc: 'Dengan memanfaatkan kekuatan WebAssembly (Wasm), kami mengambil pustaka C++ dan Rust sisi server yang kompleks dan mem-portingnya untuk dijalankan langsung di dalam browser web Anda. Ini berarti server dihadirkan ke perangkat Anda, sehingga sepenuhnya menghilangkan kebutuhan akan pengunggahan jaringan.',
    pageAboutSec3Title: 'Jaminan kami',
    pageAboutSec3Desc: 'HandleMyFile dibuat agar tetap sepenuhnya gratis. Misi kami adalah mendemokratisasi kegunaan dokumen untuk semua orang, di mana saja.',
    pageAboutSec4Title: 'Bergabunglah dengan Gerakan',
    pageAboutSec4Desc: 'Kami mengandalkan komunitas kami untuk menjaga proyek ini tetap berjalan. Bagikan HandleMyFile dengan teman, keluarga, dan rekan kerja Anda. Bersama-sama, kita dapat membangun web yang lebih aman, cepat, dan mudah diakses.',
    pagePrivacySec1Title: 'Matriks Penanganan Data',
    pagePrivacySec1Desc: 'Kami tidak mengumpulkan alamat IP. Kami tidak menyimpan file Anda. Kami tidak memerlukan registrasi email. Setiap bit data dokumen Anda tetap eksklusif di perangkat fisik Anda setiap saat.',
    pagePrivacySec2Title: 'Cara Kerja Sisi Klien',
    pagePrivacySec2Desc: 'Saat Anda memilih file di HandleMyFile, file tersebut dimuat langsung ke RAM browser Anda. Mesin WebAssembly memproses file secara lokal dan meminta pengunduhan langsung dari memori. File tidak pernah menyebar di internet.',
    pagePrivacySec3Title: 'Integrasi Pihak Ketiga',
    pagePrivacySec3Desc: 'Kami sangat mandiri. Kami tidak menyematkan pelacak analitik tersembunyi, jaringan periklanan, atau cookie pihak ketiga yang dapat membahayakan privasi Anda. Apa yang terjadi di HandleMyFile tetap di HandleMyFile.',
    pagePrivacySec4Title: 'Kepatuhan Global',
    pagePrivacySec4Desc: 'Karena arsitektur kami secara matematis mencegah kami mengakses file Anda, HandleMyFile secara inheren melampaui persyaratan privasi GDPR, CCPA, dan peraturan perlindungan data global lainnya.',
    pageTosSec1Title: 'Kebijakan Penggunaan yang Dapat Diterima',
    pageTosSec1Desc: 'Anda setuju untuk menggunakan HandleMyFile hanya untuk tujuan yang sah. Anda tidak boleh menggunakan alat kami untuk memalsukan, memanipulasi, atau memalsukan dokumen hukum, tanda pengenal pemerintah, atau materi apa pun untuk aktivitas penipuan.',
    pageTosSec2Title: 'Kekayaan Intelektual',
    pageTosSec2Desc: 'Anda memegang 100% kepemilikan dan semua hak kekayaan intelektual atas dokumen yang Anda proses menggunakan HandleMyFile. Kami tidak mengklaim hak, lisensi, atau kepemilikan atas konten Anda.',
    pageTosSec3Title: 'Modifikasi Layanan',
    pageTosSec3Desc: 'Kami berhak untuk mengubah, menangguhkan, atau menghentikan bagian mana pun dari Layanan kapan saja tanpa pemberitahuan sebelumnya. Sebagai platform sisi klien sepenuhnya, kami tidak dapat menjamin kompatibilitas dengan semua versi browser.',
    pageTosSec4Title: 'Batasan Tanggung Jawab',
    pageTosSec4Desc: 'Dalam situasi apa pun HandleMyFile, pembuatnya, atau kontributornya tidak bertanggung jawab atas segala kerusakan langsung, tidak langsung, insidental, atau konsekuensial yang diakibatkan oleh penggunaan atau ketidakmampuan menggunakan alat kami.',
    pageAboutHero: 'Alat Dokumen Demokratisasi',
    pageAboutSub: 'Kami percaya utilitas PDF dan dokumen premium harus benar-benar gratis, pribadi, dan dapat diakses oleh semua orang. HandleMyFile didukung sepenuhnya oleh WebAssembly sisi klien.',
    pagePrivacyHero: 'Gudang Aman',
    pagePrivacySub: 'File Anda tidak pernah meninggalkan perangkat Anda. Arsitektur Wasm offline 100% kami menjamin privasi dan keamanan data mutlak.',
    pageTosHero: 'Ketentuan Layanan',
    pageTosSub: 'Jelas, transparan, dan adil. Baca ketentuan yang mengatur penggunaan platform HandleMyFile.',
