    zeroUploadGuarantee: 'Mengapa Sistem Ini 100% Aman & Privat?',
    zeroUploadDetails: 'Berbeda dari platform konverter awan konvensional yang mengunggah dokumen pribadi Anda ke server jarak jauh, platform kami menjalankan mesin C/C++ WebAssembly langsung di dalam RAM peramban Anda. Dokumen rahasia Anda tidak pernah menyentuh internet.',
    faqTitle: 'Pertanyaan yang Sering Diajukan (FAQ)',
    backToHome: '← Kembali ke Semua Alat',
