    footerPricing: 'Preise',
    pagePricingHero: 'Keine Abonnements. Null Grenzen.',
    pagePricingHeroSub: 'Dokumententools der Enterprise-Klasse kosten normalerweise 20 US-Dollar pro Monat. Wir glauben, dass Privatsphäre und Nutzen ein grundlegendes Menschenrecht sein sollten. HandleMyFile ist völlig kostenlos.',
    pagePricingBadge: 'Radikal frei',
    pagePricingComp: 'Traditionelle Cloud-Tools',
    pagePricingSec3Title: 'Wie ist das möglich?',
    pagePricingSec3Desc: 'Herkömmliche Tools verursachen hohe Serverrechnungen, da sie Ihre Dateien in ihrer Cloud verarbeiten. Wir haben C++- und Rust-Engines für die Ausführung in Ihrem Browser portiert. Ihr Computer übernimmt die schwere Arbeit, was bedeutet, dass unsere Serverkosten nahezu Null sind. Diese Einsparungen geben wir direkt an Sie weiter.',
    pagePricingSec4Title: 'Nachhaltig & transparent',
    pagePricingSec4Desc: 'Damit HandleMyFile für immer 100 % kostenlos bleibt, setzen wir auf unaufdringliche Werbung und Standard-Webanalysen. Ihre Privatsphäre hat für uns jedoch oberste Priorität. Wir scannen, extrahieren oder verkaufen niemals den Inhalt Ihrer Dateien. Was im Editor passiert, bleibt im Editor.',
    pagePricingSec5Title: 'Kostenlos für geschäftliche Nutzung',
    pagePricingSec5Desc: 'Ja, Sie können HandleMyFile für Ihr Unternehmen nutzen. Tatsächlich macht uns unsere lokale Verarbeitungsarchitektur zur einzigen Plattform, die sicher genug für strenge Unternehmensumgebungen, Rechtsteams und medizinisches Fachpersonal ist.',
    pagePricingSec6Title: 'Unterstützen Sie das Projekt',
    pagePricingSec6Desc: 'Wir berechnen kein Abonnement, aber es braucht Zeit, die Domain und die Entwicklung am Leben zu halten. Wenn HandleMyFile Ihren Tag gerettet hat, sollten Sie darüber nachdenken, es mit Ihrem Team zu teilen. Mundpropaganda ist unsere einzige Marketingstrategie.',
    shareBtn: 'Teilen Sie HandleMyFile',
    footerSecurity: 'Sicherheit und Vertrauen',
    pageSecurityHero: 'Mathematische Privatsphäre. Keine Uploads.',
    pageSecurityHeroSub: 'Die meisten Dokument-Tools versprechen, dass sie Ihre Dateien nach einer Stunde löschen. Wir versprechen, dass wir Ihre Dateien überhaupt nicht sehen.',
    pageSecurityBadge: 'Vertrauenszentrum',
    pageSecuritySec2Title: 'Die WebAssembly-Revolution',
    pageSecuritySec3Title: 'Ihre Dokumente sind für uns blind',
    pageSecuritySec3Desc: 'Während wir Standardanalysen verwenden, um unser Website-Erlebnis zu verbessern, berühren unsere Skripte niemals Ihre Dokumente. Wir extrahieren keine Metadaten, Textinhalte oder Bilder. Die Dokumentverarbeitungs-Sandbox ist vollständig in Ihrem Browser-Tab enthalten.',
    pageSecuritySec4Title: 'Standardmäßige Compliance',
    pageSecuritySec4Desc: 'Da HandleMyFile nicht auf Ihre Dateien zugreifen kann, entspricht die Verwendung unserer Tools automatisch den strengsten Datenschutzgesetzen weltweit.',
    pageSecuritySec5Title: 'Vertrauen Sie uns nicht. Überprüfen Sie es.',
    pageSecuritySec5Desc: 'Sie müssen sich nicht auf unser Wort verlassen. Unsere Offline-Garantie können Sie in 3 einfachen Schritten selbst nachweisen:',
    pageSecuritySec6Title: 'Die Zukunft ist lokal',
    pageSecuritySec6Desc: 'Wir stellen uns ein Web vor, in dem Utility-Apps Ihre Hardware und Ihre Privatsphäre respektieren. Willkommen im neuen Zeitalter des clientseitigen Computings.',
    footerCompany: '会社',
    footerLanguages: 'サポートされている言語',
    footerAbout: '私たちについて',
    footerPrivacy: 'プライバシーポリシー',
    footerTos: '利用規約',
    compareTh1: '特徴',
    compareTh2: '典型的なクラウド API',
    compareTh3: 'ハンドルマイファイル',
    compareTr1Col1: 'ファイルのアップロードが必要です',
