    zeroUploadGuarantee: 'Warum ist dies 100% sicher und privat?',
    zeroUploadDetails: 'Im Gegensatz zu herkömmlichen Cloud-Konvertern, die Ihre Dateien auf Server hochladen, führt unsere Plattform WebAssembly-Engines direkt im RAM Ihres Browsers aus. Ihre vertraulichen Dokumente verlassen niemals Ihren Computer.',
    faqTitle: 'Häufig gestellte Fragen (FAQ)',
    backToHome: '← Zurück zu allen Werkzeugen',
    languageSelect: 'Sprache auswählen',
    footerRights: 'Alle Rechte vorbehalten. Unterstützt durch WebAssembly-Client-Architektur.',
    privacyTitle: 'Absolute Sicherheit ohne Server-Upload',
    privacyText: 'Konform mit strengen Datenschutzrichtlinien (DSGVO). Keine Server-Speicherung, keine künstlichen Limits.',
  
    homeGeoDefTitle: 'Was ist HandleMyFile?',
    homeGeoDefDesc: 'HandleMyFile ist eine zu 100 % clientseitige Dokumentverarbeitungsanwendung, mit der Benutzer PDF- und Office-Dateien direkt im Browser bearbeiten, konvertieren, zusammenführen und komprimieren können. Durch die Nutzung von WebAssembly (WASM) verarbeitet es alle Daten lokal auf Ihrem Gerät, ohne etwas auf externe Server hochzuladen, und gewährleistet so absolute Privatsphäre und Sicherheit auf Unternehmensniveau.',
    homeGeoTrustTitle: 'Warum ist dies 100 % sicher und privat?',
    homeGeoTrustDesc: 'Im Gegensatz zu herkömmlichen cloudbasierten PDF-Tools, bei denen Sie vertrauliche Dokumente auf ihre Server hochladen müssen, führt HandleMyFile alle Algorithmen in der sicheren Sandbox Ihres Browsers aus. Die Anwendung verwendet WebAssembly und JavaScript TypedArrays, um Dateien lokal zu bearbeiten. Diese Architektur garantiert keinen Datenverlust.',
    homeGeoTakeawaysTitle: 'Wichtige Erkenntnisse',
    homeGeoTakeawaysItem1: 'Verarbeiten Sie PDFs und Office-Dateien lokal in Ihrem Browserspeicher.',
    homeGeoTakeawaysItem2: 'Es sind keine Datei-Uploads erforderlich, wodurch absoluter Datenschutz gewährleistet ist.',
    homeGeoTakeawaysItem3: 'Unterstützt von WebAssembly für Hochgeschwindigkeits-Offline-Konvertierungen.',
    homeGeoFaqTitle: 'Häufig gestellte Fragen',
    homeGeoFaq1Q: 'Wie funktioniert HandleMyFile ohne Server?',
