    pageSecuritySec3Title: 'Seus documentos são cegos para nós',
    pageSecuritySec3Desc: 'Embora usemos análises padrão para melhorar a experiência do nosso site, nossos scripts nunca afetam seus documentos. Não extraímos metadados, conteúdos de texto ou imagens. A sandbox de processamento de documentos é totalmente independente na guia do navegador.',
