    pageCompareExpertTitle: 'بنيت للخصوصية',
    pageCompareExpertQuote: 'قد يكون تحميل مستندات الشركة السرية إلى واجهات برمجة التطبيقات السحابية بمثابة ثغرة أمنية للفرق البعيدة. توفر أدوات المعالجة من جانب العميل مثل HandleMyFile بنية الثقة المعدومة المناسبة للتعامل مع ملفات PDF الحساسة محليًا.',
    pageCompareExpertRole: 'الخصوصية حسب التصميم',
    pageCompareSec3Desc: 'باستخدام الأدوات السحابية القديمة، إذا كنت تريد دمج ثلاثة ملفات PDF بحجم 50 ميجابايت، فستضطر إلى تحميل 150 ميجابايت من البيانات. ثم تنتظر حتى يقوم خادمهم بمعالجتها. ثم تقوم بتنزيل نتيجة 150 ميجابايت. هذا هو عنق الزجاجة في الشبكة بسعة 300 ميجابايت. يقوم HandleMyFile بمعالجة 150 ميجابايت على الفور على القرص المحلي الخاص بك باستخدام WebAssembly.',
    pageCompareSec4Title: 'حافظ على خصوصية بياناتك',
    pageCompareSec4Desc: 'تحتفظ العديد من أدوات PDF عبر الإنترنت بالحق في مسح المستندات التي تم تحميلها ضوئيًا. تضمن بنيتنا غير المتصلة بالإنترنت الخصوصية افتراضيًا مجانًا. ملفاتك لا تترك جهازك أبدًا.',
    pageCompareSec5Title: 'الهروب من فخ حجم الملف',
    pageCompareSec5Desc: 'غالبًا ما تحد واجهات برمجة التطبيقات السحابية من سير عملك بحدود 5 ميجابايت. يستخدم HandleMyFile ذاكرة الوصول العشوائي (RAM) بجهازك، مما يعني أنه يمكنك معالجة ملفات يزيد حجمها عن 1 جيجابايت محليًا إذا كان جهاز الكمبيوتر الخاص بك يمكنه التعامل معها.',
    pageCompareSec6Title: 'التبديل اليوم',
    pageCompareSec6Desc: 'توقف عن المساومة على السرعة والخصوصية والتكلفة. انضم إلى آلاف المحترفين الذين تحولوا بالفعل إلى أسرع مجموعة أدوات للمستندات غير المتصلة بالإنترنت على الويب.',
    pageLangHero: 'اللغات المدعومة',
    pageLangHeroSub: 'تمت ترجمة HandleMyFile بالكامل إلى 30 لغة.',
    pageLangBadge: 'الوصول العالمي',
    pageLangSec2Title: 'التوطين الأصلي',
    pageLangSec3Title: 'كسر حواجز اللغة',
    pageLangSec3Desc: 'استخدم أدوات المستندات غير المتصلة بالإنترنت بلغتك الأم. نحن ندعم اللغات التي تكتب من اليسار إلى اليمين ومن اليمين إلى اليسار مع الترجمة الكاملة لواجهة المستخدم.',
    pageLangSec4Title: 'لا حاجة للترجمة السحابية',
    pageLangSec4Desc: 'يتم تجميع كل نصوص واجهة المستخدم مباشرة في التطبيق، مما يعني أنك لا تحتاج إلى الوصول إلى الإنترنت لتبديل اللغات.',
    pageLangSec5Title: 'التبديل السلس',
    pageLangSec5Desc: 'قم بتغيير اللغات على الفور دون إعادة تحميل التطبيق.',
    pageLangSec6Title: 'هل أنت مستعد للبدء؟',
    pageLangSec6Desc: 'حدد لغتك المفضلة واستمتع بتجربة أسرع أدوات المستندات غير المتصلة بالإنترنت على الويب.',
    footerUseCases: 'Casos de uso',
    pageUseCasesHero: 'Construído para todas as profissões',
    pageUseCasesHeroSub: 'De ambientes jurídicos rigorosos a agências criativas, descubra por que os profissionais confiam em nossa arquitetura de processamento do lado do cliente.',
    pageUseCasesBadge: 'Soluções para a Indústria',
    pageUseCasesSec2Title: 'Escritórios jurídicos e de advocacia',
    pageUseCasesSec2Desc: 'Os advogados lidam com NDAs, contratos e registros judiciais altamente confidenciais. O upload desses documentos para APIs de nuvem aleatórias é um grande problema. Com o HandleMyFile, as equipes jurídicas podem redigir, mesclar e dividir arquivos de casos em PDF totalmente offline, garantindo absoluta confidencialidade do cliente.',
    pageUseCasesSec3Title: 'Recursos Humanos (RH)',
    pageUseCasesSec3Desc: 'Os departamentos de RH lidam com PII (informações de identificação pessoal) diariamente. A digitalização de identidades, o manuseio de planilhas de folha de pagamento e o gerenciamento de cartas de oferta exigem conformidade estrita com GDPR/CCPA. HandleMyFile permite que profissionais de RH gerenciem esses arquivos sem violar as políticas internas de segurança de TI.',
    pageUseCasesSec4Title: 'Estudantes e Educação',
    pageUseCasesSec4Desc: 'Os alunos não deveriam ter que pagar US$ 20/mês apenas para mesclar suas tarefas de projeto em grupo ou compactar uma apresentação para caber no limite de upload de 5 MB do portal universitário. HandleMyFile fornece acesso ilimitado a ferramentas premium gratuitamente, com limite zero de tamanho de arquivo.',
    pageUseCasesSec5Title: 'Imóveis e Agentes',
    pageUseCasesSec5Desc: 'Os corretores imobiliários lidam com enormes folhetos de propriedades repletos de imagens de alta resolução que são grandes demais para serem enviadas por e-mail aos clientes. Eles também precisam colocar rapidamente marcas d’água em planos de propriedades e assinar contratos de locação. HandleMyFile lida com arquivos de mais de 100 MB instantaneamente.',
    pageUseCasesSec6Title: 'Encontre seu próprio caso de uso',
    pageUseCasesSec6Desc: 'Não importa o seu setor, se você trabalha com documentos, o HandleMyFile é a maneira mais segura e rápida de realizar o trabalho. Experimente nosso conjunto completo de mais de 20 ferramentas hoje.',
    footerCompare: 'Comparar',
    pageCompareHero: 'HandleMyFile versus o resto',
    pageCompareHeroSub: 'Cansado de esperar o upload dos arquivos? Frustrado com os limites de arquivo de 5 MB? Descubra por que os profissionais estão migrando para ferramentas de documentos do lado do cliente.',
    pageCompareBadge: 'A alternativa inteligente',
    pageCompareSec2Title: 'Comparação de recursos',
