    footerPricing: 'Цены',
    pagePricingHero: 'Нулевые подписки. Нулевые ограничения.',
    pagePricingHeroSub: 'Инструменты для работы с документами корпоративного уровня обычно стоят 20 долларов в месяц. Мы считаем, что конфиденциальность и полезность должны быть фундаментальными правами человека. HandleMyFile полностью бесплатен.',
    pagePricingBadge: 'Радикально бесплатно',
    pagePricingComp: 'Традиционные облачные инструменты',
    pagePricingSec3Title: 'Как это возможно?',
    pagePricingSec3Desc: 'Традиционные инструменты требуют дорогостоящих счетов за сервер, поскольку они обрабатывают ваши файлы в своем облаке. Мы портировали движки C++ и Rust для работы в вашем браузере. Ваш компьютер выполняет тяжелую работу, а это означает, что затраты на наш сервер близки к нулю. Мы передаем эту экономию непосредственно вам.',
    pagePricingSec4Title: 'Устойчивое и прозрачное',
    pagePricingSec4Desc: 'Чтобы HandleMyFile всегда оставался на 100% бесплатным, мы полагаемся на ненавязчивую рекламу и стандартную веб-аналитику. Однако ваша конфиденциальность является нашим главным приоритетом. Мы никогда не сканируем, не извлекаем и не продаем содержимое ваших файлов. Что происходит в редакторе, остаётся в редакторе.',
    pagePricingSec5Title: 'Бесплатно для делового использования',
    pagePricingSec5Desc: 'Да, вы можете использовать HandleMyFile для своей компании. Фактически, наша локальная архитектура обработки делает нас единственной платформой, достаточно безопасной для строгих корпоративных условий, юридических групп и медицинских работников.',
    pagePricingSec6Title: 'Поддержите проект',
    pagePricingSec6Desc: 'Мы не взимаем плату за подписку, но поддержание домена и его разработка требуют времени. Если HandleMyFile спас ваше время, подумайте о том, чтобы поделиться им со своей командой. Сарафанное радио — наша единственная маркетинговая стратегия.',
    shareBtn: 'Поделиться',
    footerSecurity: 'Безопасность и доверие',
    pageSecurityHero: 'Математическая конфиденциальность. Ноль загрузок.',
    pageSecurityHeroSub: 'Большинство инструментов для работы с документами обещают удалить ваши файлы через 1 час. Мы обещаем, что никогда не увидим ваши файлы.',
    pageSecurityBadge: 'Трастовый центр',
    pageSecuritySec2Title: 'Революция в веб-сборке',
    pageSecuritySec3Title: 'Ваши документы для нас слепы',
    pageSecuritySec3Desc: 'Хотя мы используем стандартную аналитику для улучшения работы нашего веб-сайта, наши скрипты никогда не затрагивают ваши документы. Мы не извлекаем метаданные, текстовое содержимое или изображения. Песочница обработки документов полностью автономна на вкладке вашего браузера.',
    pageSecuritySec4Title: 'Соответствие по умолчанию',
    pageSecuritySec4Desc: 'Поскольку HandleMyFile не может получить доступ к вашим файлам, использование наших инструментов автоматически соответствует самым строгим законам о защите данных во всем мире.',
