    pageCompareSec3Desc: 'लीगेसी क्लाउड टूल के साथ, यदि आप तीन 50 एमबी पीडीएफ को मर्ज करना चाहते हैं, तो आपको 150 एमबी डेटा अपलोड करने के लिए मजबूर किया जाता है। फिर आप उनके सर्वर द्वारा इसे संसाधित करने की प्रतीक्षा करें। फिर आप 150एमबी रिजल्ट डाउनलोड करें। यह 300एमबी नेटवर्क बाधा है। HandleMyFile WebAssembly का उपयोग करके आपकी स्थानीय डिस्क पर तुरंत 150MB प्रोसेस करता है।',
    pageCompareSec4Title: 'अपना डेटा निजी रखें',
    pageCompareSec4Desc: 'कई ऑनलाइन पीडीएफ टूल आपके अपलोड किए गए दस्तावेज़ों को स्कैन करने का अधिकार सुरक्षित रखते हैं। हमारा ऑफ़लाइन आर्किटेक्चर डिफ़ॉल्ट रूप से निःशुल्क गोपनीयता की गारंटी देता है। आपकी फ़ाइलें कभी भी आपका डिवाइस नहीं छोड़तीं।',
