    footerUseCases: 'Варианты использования',
    pageUseCasesHero: 'Создан для каждой профессии',
    pageUseCasesHeroSub: 'От строгих юридических условий до креативных агентств — узнайте, почему профессионалы доверяют нашей архитектуре обработки данных на стороне клиента.',
    pageUseCasesBadge: 'Отраслевые решения',
    pageUseCasesSec2Title: 'Юридические и юридические фирмы',
    pageUseCasesSec2Desc: 'Адвокаты обрабатывают строго конфиденциальные соглашения о неразглашении, контракты и судебные документы. Загрузка этих документов в случайные облачные API — это серьезная ответственность. С помощью HandleMyFile юридические группы могут редактировать, объединять и разделять PDF-файлы дел полностью в автономном режиме, обеспечивая абсолютную конфиденциальность клиента.',
    pageUseCasesSec3Title: 'Человеческие ресурсы (HR)',
    pageUseCasesSec3Desc: 'Отделы кадров ежедневно работают с PII (персональной информацией). Сканирование идентификаторов, обработка таблиц заработной платы и управление письмами с предложениями требуют строгого соблюдения GDPR/CCPA. HandleMyFile позволяет специалистам по персоналу управлять этими файлами, не нарушая внутренние политики ИТ-безопасности.',
    pageUseCasesSec4Title: 'Студенты и образование',
    pageUseCasesSec4Desc: 'Студентам не придется платить 20 долларов в месяц только за то, чтобы объединить задания по групповым проектам или сжать презентацию в соответствии с ограничением загрузки университетского портала в 5 МБ. HandleMyFile предоставляет неограниченный бесплатный доступ к инструментам премиум-класса с нулевыми ограничениями на размер файла.',
    pageUseCasesSec5Title: 'Недвижимость и агенты',
    pageUseCasesSec5Desc: 'Агенты по недвижимости работают с огромными брошюрами о недвижимости, заполненными изображениями высокого разрешения, которые слишком велики для отправки по электронной почте клиентам. Им также необходимо быстро поставить водяные знаки на планах собственности и подписать договоры аренды. HandleMyFile мгновенно обрабатывает файлы размером более 100 МБ.',
    pageUseCasesSec6Title: 'Найдите свой вариант использования',
    pageUseCasesSec6Desc: 'Независимо от вашей отрасли, если вы работаете с документами, HandleMyFile — это самый безопасный и быстрый способ выполнить работу. Попробуйте наш полный набор из более чем 20 инструментов сегодня.',
