    homeGeoFaq2Q: 'Есть ли какие-либо ограничения на размер файла?',
    homeGeoFaq2A: 'Нет. Поскольку обработка происходит на вашем локальном устройстве, единственным ограничением является доступная оперативная память вашего компьютера.',
