    pageUseCasesBadge: 'حلول الصناعة',
    pageUseCasesSec2Title: 'مكاتب المحاماة والقانون',
    pageUseCasesSec2Desc: 'يتعامل المحامون مع اتفاقيات عدم الإفصاح والعقود وملفات المحكمة السرية للغاية. يعد تحميل هذه المستندات إلى واجهات برمجة التطبيقات السحابية العشوائية مسؤولية كبيرة. باستخدام HandleMyFile، يمكن للفرق القانونية تنقيح ودمج وتقسيم ملفات قضايا PDF بالكامل دون الاتصال بالإنترنت، مما يضمن السرية المطلقة للعميل.',
    pageUseCasesSec3Title: 'الموارد البشرية (HR)',
    pageUseCasesSec3Desc: 'تتعامل أقسام الموارد البشرية مع معلومات تحديد الهوية الشخصية (PII) على أساس يومي. يتطلب مسح المعرفات ضوئيًا والتعامل مع جداول بيانات الرواتب وإدارة خطابات العرض امتثالًا صارمًا للقانون العام لحماية البيانات/CCPA. يتيح HandleMyFile لمحترفي الموارد البشرية إدارة هذه الملفات دون انتهاك سياسات أمان تكنولوجيا المعلومات الداخلية.',
    pageUseCasesSec4Title: 'الطلاب والتعليم',
    pageUseCasesSec4Desc: 'لا يجب على الطلاب دفع 20 دولارًا شهريًا فقط لدمج مهام مشروعهم الجماعي أو ضغط العرض التقديمي ليناسب حد التحميل لبوابة الجامعة وهو 5 ميجابايت. يوفر HandleMyFile وصولاً غير محدود إلى الأدوات المتميزة مجانًا، مع عدم وجود حدود لحجم الملف.',
    pageUseCasesSec5Title: 'العقارات والوكلاء',
    pageUseCasesSec5Desc: 'يتعامل وكلاء العقارات مع كتيبات عقارية ضخمة مليئة بصور عالية الدقة كبيرة جدًا بحيث لا يمكن إرسالها عبر البريد الإلكتروني إلى العملاء. كما يحتاجون أيضًا إلى وضع علامة مائية بسرعة على خطط العقارات وتوقيع اتفاقيات الإيجار. يعالج HandleMyFile ملفات يزيد حجمها عن 100 ميجابايت على الفور.',
    pageUseCasesSec6Title: 'ابحث عن حالة الاستخدام الخاصة بك',
    pageUseCasesSec6Desc: 'بغض النظر عن مجال عملك، إذا كنت تعمل مع المستندات، فإن HandleMyFile هو الطريقة الأكثر أمانًا والأسرع لإنجاز المهمة. جرب مجموعتنا الكاملة التي تضم أكثر من 20 أداة اليوم.',
