    privacyTitle: 'أمان التحميل المطلق',
    privacyText: 'متوافق مع متطلبات الخصوصية القانونية للمؤسسة (GDPR/HIPAA). لا يوجد تخزين على الخادم، ولا تسجيل للبيانات، ولا حدود مصطنعة.',
    pageAboutSec1Title: 'قصة الأصل',
    pageAboutSec1Desc: 'لقد شعرنا بالإحباط بسبب نظام حظر الاشتراك غير المدفوع المستمر وتسريبات الخصوصية لأدوات المستندات التقليدية عبر الإنترنت. يبدو أن تحميل الملفات الحساسة إلى خوادم عشوائية أمر خاطئ بطبيعته. لقد قمنا ببناء HandleMyFile لإثبات أن الأدوات على مستوى المؤسسات يمكن أن تكون مجانية وسريعة وآمنة تمامًا.',
    pageAboutSec2Title: 'كومة التكنولوجيا',
    pageAboutSec2Desc: 'من خلال الاستفادة من قوة WebAssembly (Wasm)، أخذنا مكتبات C++ وRust المعقدة من جانب الخادم وقمنا بنقلها للتشغيل مباشرة داخل متصفح الويب الخاص بك. وهذا يعني أن الخادم قد تم إحضاره إلى جهازك، مما يلغي الحاجة إلى التحميلات عبر الشبكة تمامًا.',
    pageAboutSec3Title: 'ضماننا',
    pageAboutSec3Desc: 'تم تصميم HandleMyFile ليظل مجانيًا تمامًا. مهمتنا هي إضفاء الطابع الديمقراطي على أدوات مساعدة المستندات للجميع وفي كل مكان.',
    pageAboutSec4Title: 'انضم إلى الحركة',
    pageAboutSec4Desc: 'نحن نعتمد على مجتمعنا للحفاظ على هذا المشروع على قيد الحياة. شارك HandleMyFile مع أصدقائك وعائلتك وزملائك في العمل. معًا، يمكننا بناء شبكة ويب أكثر أمانًا وسرعة وسهولة في الوصول إليها.',
    pagePrivacySec1Title: 'مصفوفة معالجة البيانات',
    pagePrivacySec1Desc: 'نحن لا نجمع عناوين IP. نحن لا نقوم بتخزين الملفات الخاصة بك. نحن لا نطلب تسجيلات البريد الإلكتروني. يظل كل جزء من بيانات مستندك حصريًا على جهازك الفعلي في جميع الأوقات.',
    pagePrivacySec2Title: 'كيف يعمل جانب العميل',
    pagePrivacySec2Desc: 'عند تحديد ملف على HandleMyFile، يتم تحميله مباشرة في ذاكرة الوصول العشوائي (RAM) الخاصة بالمتصفح الخاص بك. يقوم محرك WebAssembly بمعالجة الملف محليًا ويطالبك بالتنزيل مباشرة من الذاكرة. لا ينتقل الملف مطلقًا عبر الإنترنت.',
    pagePrivacySec3Title: 'تكاملات الطرف الثالث',
    pagePrivacySec3Desc: 'نحن مستقلون بشدة. نحن لا نقوم بتضمين أدوات تتبع التحليلات المخفية أو شبكات الإعلانات أو ملفات تعريف الارتباط التابعة لجهات خارجية والتي يمكن أن تعرض خصوصيتك للخطر. ما يحدث في HandleMyFile يبقى في HandleMyFile.',
    pagePrivacySec4Title: 'الامتثال العالمي',
    pagePrivacySec4Desc: 'نظرًا لأن بنيتنا تمنعنا رياضيًا من الوصول إلى ملفاتك، فإن HandleMyFile يتجاوز بطبيعته متطلبات الخصوصية الخاصة باللوائح العامة لحماية البيانات (GDPR) وCCPA وغيرها من لوائح حماية البيانات العالمية.',
    pageTosSec1Title: 'سياسة الاستخدام المقبول',
    pageTosSec1Desc: 'أنت توافق على استخدام HandleMyFile فقط للأغراض القانونية. يجب ألا تستخدم أدواتنا لتزوير أو التلاعب أو تزوير المستندات القانونية أو بطاقات الهوية الحكومية أو أي مواد لأنشطة احتيالية.',
    pageTosSec2Title: 'الملكية الفكرية',
