    pageTosSec4Desc: 'لن تتحمل HandleMyFile أو منشئوها أو مساهموها تحت أي ظرف من الظروف المسؤولية عن أي أضرار مباشرة أو غير مباشرة أو عرضية أو تبعية ناتجة عن استخدام أدواتنا أو عدم القدرة على استخدامها.',
  
    homeGeoDefTitle: 'ما هو هاندليميفيل؟',
    homeGeoDefDesc: 'HandleMyFile هو تطبيق معالجة مستندات من جانب العميل بنسبة 100% يسمح للمستخدمين بتحرير ملفات PDF وOffice وتحويلها ودمجها وضغطها مباشرة في المتصفح. ومن خلال الاستفادة من WebAssembly (WASM)، فإنه يعالج جميع البيانات محليًا على جهازك دون تحميل أي شيء إلى خوادم خارجية، مما يضمن الخصوصية المطلقة والأمان على مستوى المؤسسة.',
    homeGeoTrustTitle: 'لماذا يعد هذا آمنًا وخاصًا بنسبة 100%؟',
    homeGeoTrustDesc: 'على عكس أدوات PDF التقليدية المستندة إلى السحابة والتي تتطلب منك تحميل مستندات حساسة إلى خوادمها، يقوم HandleMyFile بتنفيذ جميع الخوارزميات داخل صندوق الحماية الآمن للمتصفح الخاص بك. يستخدم التطبيق WebAssembly وJavaScript TypedArrays لمعالجة الملفات محليًا. تضمن هذه البنية عدم تسرب البيانات.',
