    homeGeoTakeawaysItem3: 'مدعوم من WebAssembly للتحويلات عالية السرعة دون الاتصال بالإنترنت.',
    homeGeoFaqTitle: 'الأسئلة المتداولة',
    homeGeoFaq1Q: 'كيف يعمل HandleMyFile بدون خادم؟',
    homeGeoFaq1A: 'يستخدم WebAssembly (WASM) لتشغيل مكتبات معالجة C++ وRust الثقيلة مباشرة داخل محرك متصفح الويب الخاص بك.',
    homeGeoFaq2Q: 'هل هناك أي حدود لحجم الملف؟',
