    pageCompareExpertQuote: 'Het uploaden van vertrouwelijke bedrijfsdocumenten naar cloud-API\'s kan een kwetsbaarheid zijn voor externe teams. Verwerkingstools aan de clientzijde, zoals HandleMyFile, bieden een zero-trust-architectuur die geschikt is voor het lokaal verwerken van gevoelige PDF\'s.',
    pageCompareExpertRole: 'Privacy door ontwerp',
    pageCompareSec3Desc: 'Als u met oudere cloudtools drie PDF\'s van 50 MB wilt samenvoegen, moet u 150 MB aan gegevens uploaden. Vervolgens wacht je tot hun server het heeft verwerkt. Vervolgens download je het resultaat van 150 MB. Dat is een netwerkknelpunt van 300 MB. HandleMyFile verwerkt de 150 MB direct op uw lokale schijf met behulp van WebAssembly.',
