    pageUseCasesSec3Title: 'मानव संसाधन (एचआर)',
    pageUseCasesSec3Desc: 'मानव संसाधन विभाग दैनिक आधार पर पीआईआई (व्यक्तिगत पहचान योग्य जानकारी) से निपटते हैं। आईडी को स्कैन करने, पेरोल स्प्रेडशीट को संभालने और ऑफर लेटर को प्रबंधित करने के लिए सख्त जीडीपीआर/सीसीपीए अनुपालन की आवश्यकता होती है। HandleMyFile HR पेशेवरों को आंतरिक IT सुरक्षा नीतियों का उल्लंघन किए बिना इन फ़ाइलों को प्रबंधित करने देता है।',
