    pagePricingHeroSub: 'Gli strumenti per documenti di livello aziendale in genere costano $ 20 al mese. Crediamo che la privacy e l\'utilità debbano essere un diritto umano fondamentale. HandleMyFile è completamente gratuito.',
    pagePricingBadge: 'Radicalmente libero',
    pagePricingComp: 'Strumenti cloud tradizionali',
    pagePricingSec3Title: 'Com\'è possibile?',
    pagePricingSec3Desc: 'Gli strumenti tradizionali hanno fatture costose per i server perché elaborano i file sul loro cloud. Abbiamo portato i motori C++ e Rust per l\'esecuzione nel tuo browser. Il tuo computer fa il lavoro pesante, il che significa che i costi dei nostri server sono prossimi allo zero. Passiamo questi risparmi direttamente a te.',
    pagePricingSec4Title: 'Sostenibile e trasparente',
    pagePricingSec4Desc: 'Per mantenere HandleMyFile gratuito al 100% per sempre, ci affidiamo a pubblicità non intrusive e analisi web standard. Tuttavia, la tua privacy è la nostra massima priorità. Non scansioniamo, estraiamo o vendiamo mai il contenuto dei tuoi file. Ciò che accade nell\'editor, rimane nell\'editor.',
    pagePricingSec5Title: 'Gratuito per uso aziendale',
    pagePricingSec5Desc: 'Sì, puoi utilizzare HandleMyFile per la tua azienda. In effetti, la nostra architettura di elaborazione locale ci rende l’unica piattaforma sufficientemente sicura per ambienti aziendali, team legali e professionisti sanitari severi.',
    pagePricingSec6Title: 'Sostieni il progetto',
    pagePricingSec6Desc: 'Non addebitiamo alcun abbonamento, ma mantenere vivo il dominio e lo sviluppo richiede tempo. Se HandleMyFile ti ha salvato la giornata, considera di condividerlo con il tuo team. Il passaparola è la nostra unica strategia di marketing.',
    shareBtn: 'Condividi HandleMyFile',
    footerSecurity: 'Sicurezza e fiducia',
    pageSecurityHero: 'Privacy matematica. Zero caricamenti.',
    pageSecurityHeroSub: 'La maggior parte degli strumenti per documenti promettono di eliminare i file dopo 1 ora. Promettiamo che non vedremo mai i tuoi file in primo luogo.',
    pageSecurityBadge: 'Centro fiducia',
    pageSecuritySec2Title: 'La rivoluzione del WebAssembly',
    pageSecuritySec3Title: 'I tuoi documenti sono ciechi per noi',
    pageSecuritySec3Desc: 'Sebbene utilizziamo analisi standard per migliorare l\'esperienza del nostro sito Web, i nostri script non toccano mai i tuoi documenti. Non estraiamo metadati, contenuti testuali o immagini. La sandbox di elaborazione dei documenti è completamente autonoma nella scheda del browser.',
    pageSecuritySec4Title: 'Conformità per impostazione predefinita',
    pageSecuritySec4Desc: 'Poiché HandleMyFile non può accedere ai tuoi file, l\'utilizzo dei nostri strumenti è automaticamente conforme alle più severe leggi sulla protezione dei dati a livello mondiale.',
    pageSecuritySec5Title: 'Non fidarti di noi. Verificalo.',
    pageSecuritySec5Desc: 'Non devi crederci sulla parola. Puoi provare tu stesso la nostra garanzia offline in 3 semplici passaggi:',
    pageSecuritySec6Title: 'Il futuro è locale',
    pageSecuritySec6Desc: 'Immaginiamo un web in cui le app di utilità rispettino il tuo hardware e la tua privacy. Benvenuti nella nuova era dell\'elaborazione lato client.',
