    pageCompareExpertTitle: 'Gizlilik için Tasarlandı',
    pageCompareExpertQuote: 'Gizli kurumsal belgelerin bulut API\'lerine yüklenmesi uzak ekipler için bir güvenlik açığı oluşturabilir. HandleMyFile gibi istemci tarafı işleme araçları, hassas PDF\'lerin yerel olarak işlenmesine uygun sıfır güven mimarisi sağlar.',
    pageCompareExpertRole: 'Tasarıma Göre Gizlilik',
    pageCompareSec3Desc: 'Eski bulut araçlarıyla, 50 MB\'lık üç PDF\'yi birleştirmek istiyorsanız 150 MB\'lık veri yüklemeniz gerekir. Daha sonra sunucularının bunu işlemesini beklersiniz. Daha sonra 150MB sonucunu indirirsiniz. Bu 300 MB\'lık bir ağ darboğazıdır. HandleMyFile, WebAssembly\'ı kullanarak yerel diskinizdeki 150 MB\'lık alanı anında işler.',
    pageCompareSec4Title: 'Verilerinizi Gizli Tutun',
    pageCompareSec4Desc: 'Birçok çevrimiçi PDF aracı, yüklediğiniz belgelerinizi tarama hakkını saklı tutar. Çevrimdışı mimarimiz varsayılan olarak gizliliği ücretsiz olarak garanti eder. Dosyalarınız asla cihazınızdan ayrılmaz.',
    pageCompareSec5Title: 'Dosya Boyutu Tuzağından Kurtulun',
    pageCompareSec5Desc: 'Cloud API\'ler genellikle iş akışınızı 5 MB\'lık sınırlarla sınırlar. HandleMyFile, cihazınızın RAM\'ini kullanır; bu, eğer bilgisayarınız bunu kaldırabiliyorsa, 1GB\'tan fazla dosyayı yerel olarak işleyebileceğiniz anlamına gelir.',
    pageCompareSec6Title: 'Bugün Geçiş Yapın',
    pageCompareSec6Desc: 'Hız, gizlilik ve maliyetten ödün vermeyi bırakın. Web\'deki en hızlı çevrimdışı belge araç setine geçmiş olan binlerce profesyonele katılın.',
    pageLangHero: 'Desteklenen Diller',
    pageLangHeroSub: 'HandleMyFile 30 dilde tamamen yerelleştirilmiştir.',
    pageLangBadge: 'Küresel Erişim',
    pageLangSec2Title: 'Yerel Yerelleştirme',
    pageLangSec3Title: 'Dil Engellerini Aşın',
    pageLangSec3Desc: 'Çevrimdışı belge araçlarımızı ana dilinizde kullanın. Tam kullanıcı arayüzü yerelleştirmesiyle soldan sağa ve sağdan sola dilleri destekliyoruz.',
    pageLangSec4Title: 'Bulut Çevirisine Gerek Yok',
    pageLangSec4Desc: 'Tüm kullanıcı arayüzü metni doğrudan uygulamanın içinde paketlenir; bu, dil değiştirmek için internet erişimine ihtiyacınız olmadığı anlamına gelir.',
    pageLangSec5Title: 'Kusursuz Anahtarlama',
    pageLangSec5Desc: 'Uygulamayı yeniden yüklemeden dilleri anında değiştirin.',
    pageLangSec6Title: 'Başlamaya Hazır mısınız?',
    pageLangSec6Desc: 'Tercih ettiğiniz dili seçin ve web üzerindeki en hızlı çevrimdışı belge araçlarını deneyimleyin.',
    footerUseCases: 'Casi d\'uso',
    pageUseCasesHero: 'Costruito per ogni professione',
    pageUseCasesHeroSub: 'Dagli ambienti legali rigorosi alle agenzie creative, scopri perché i professionisti si affidano alla nostra architettura di elaborazione lato client.',
    pageUseCasesBadge: 'Soluzioni per l\'industria',
    pageUseCasesSec2Title: 'Studi legali e legali',
    pageUseCasesSec2Desc: 'Gli avvocati gestiscono NDA, contratti e documenti giudiziari altamente riservati. Il caricamento di questi documenti su API cloud casuali è una delle principali responsabilità. Con HandleMyFile, i team legali possono redigere, unire e dividere i file PDF dei casi completamente offline, garantendo l\'assoluta riservatezza del cliente.',
    pageUseCasesSec3Title: 'Risorse umane (HR)',
    pageUseCasesSec3Desc: 'I dipartimenti delle risorse umane si occupano quotidianamente di PII (informazioni di identificazione personale). La scansione degli ID, la gestione dei fogli di calcolo delle buste paga e la gestione delle lettere di offerta richiedono una rigorosa conformità al GDPR/CCPA. HandleMyFile consente ai professionisti delle risorse umane di gestire questi file senza violare le policy di sicurezza IT interne.',
    pageUseCasesSec4Title: 'Studenti e istruzione',
    pageUseCasesSec4Desc: 'Gli studenti non dovrebbero dover pagare $ 20 al mese solo per unire i compiti di progetto di gruppo o comprimere una presentazione per adattarla al limite di caricamento di 5 MB del portale universitario. HandleMyFile fornisce accesso illimitato e gratuito a strumenti premium, senza limiti di dimensione dei file.',
    pageUseCasesSec5Title: 'Immobiliare e agenti',
    pageUseCasesSec5Desc: 'Gli agenti immobiliari gestiscono enormi brochure immobiliari piene di immagini ad alta risoluzione che sono troppo grandi per essere inviate via email ai clienti. Devono inoltre filigranare rapidamente i piani immobiliari e firmare contratti di locazione. HandleMyFile gestisce istantaneamente file da 100 MB+.',
    pageUseCasesSec6Title: 'Trova il tuo caso d\'uso',
    pageUseCasesSec6Desc: 'Non importa il tuo settore, se lavori con documenti, HandleMyFile è il modo più sicuro e veloce per portare a termine il lavoro. Prova oggi stesso la nostra suite completa di oltre 20 strumenti.',
    footerCompare: 'Confrontare',
    pageCompareHero: 'HandleMyFile contro il resto',
    pageCompareHeroSub: 'Stanco di aspettare che i file vengano caricati? Frustrato dai limiti dei file da 5 MB? Scopri perché i professionisti stanno passando agli strumenti documentali lato client.',
    pageCompareBadge: 'L\'alternativa intelligente',
    pageCompareSec2Title: 'Confronto delle funzionalità',
    pageCompareSec3Title: 'Smetti di aspettare sulle barre di avanzamento',
