    footerPricing: '가격',
    pagePricingHero: '구독이 없습니다. 제로 한계.',
    pagePricingHeroSub: '엔터프라이즈급 문서 도구의 비용은 일반적으로 월 20달러입니다. 우리는 개인정보 보호와 유용성이 기본적인 인권이어야 한다고 믿습니다. HandleMyFile은 완전 무료입니다.',
    pagePricingBadge: '근본적으로 무료',
    pagePricingComp: '기존 클라우드 도구',
    pagePricingSec3Title: '이것이 어떻게 가능합니까?',
    pagePricingSec3Desc: '기존 도구는 클라우드에서 파일을 처리하기 때문에 서버 비용이 많이 듭니다. 귀하의 브라우저 내에서 실행되도록 C++ 및 Rust 엔진을 포팅했습니다. 귀하의 컴퓨터가 무거운 작업을 수행하므로 서버 비용이 거의 0에 가깝습니다. 우리는 이러한 절감액을 귀하에게 직접 전달합니다.',
    pagePricingSec4Title: '지속 가능하고 투명함',
    pagePricingSec4Desc: 'HandleMyFile을 영원히 100% 무료로 유지하기 위해 우리는 방해가 되지 않는 광고와 표준 웹 분석을 사용합니다. 그러나 귀하의 개인 정보 보호는 우리의 최우선 사항입니다. 우리는 귀하의 파일 내용을 스캔, 추출 또는 판매하지 않습니다. 편집기에서 발생한 일은 편집기에 그대로 유지됩니다.',
    pagePricingSec5Title: '기업용으로 무료',
    pagePricingSec5Desc: '예, 회사에서 HandleMyFile을 사용할 수 있습니다. 실제로 당사의 로컬 처리 아키텍처는 당사를 엄격한 기업 환경, 법률 팀 및 의료 전문가에게 충분히 안전한 유일한 플랫폼으로 만듭니다.',
    pagePricingSec6Title: '프로젝트 지원',
    pagePricingSec6Desc: '구독료를 청구하지 않지만 도메인과 개발을 유지하는 데는 시간이 걸립니다. HandleMyFile이 하루를 절약했다면 팀과 공유해 보세요. 입소문은 우리의 유일한 마케팅 전략입니다.',
    shareBtn: 'HandleMyFile 공유',
