    pageSecuritySec3Desc: '우리는 웹사이트 경험을 개선하기 위해 표준 분석을 사용하지만, 우리의 스크립트는 결코 귀하의 문서에 영향을 미치지 않습니다. 메타데이터, 텍스트 콘텐츠 또는 이미지는 추출하지 않습니다. 문서 처리 샌드박스는 브라우저 탭 내에 완전히 독립적으로 포함되어 있습니다.',
