    pageCompareExpertQuote: 'Przesyłanie poufnych dokumentów firmowych do interfejsów API w chmurze może stanowić lukę w zabezpieczeniach zdalnych zespołów. Narzędzia do przetwarzania po stronie klienta, takie jak HandleMyFile, zapewniają architekturę zerowego zaufania odpowiednią do lokalnej obsługi wrażliwych plików PDF.',
    pageCompareExpertRole: 'Prywatność już w fazie projektowania',
    footerCompany: 'Công ty',
    footerLanguages: 'Ngôn ngữ được hỗ trợ',
    pageCompareSec3Desc: 'Với các công cụ đám mây cũ, nếu muốn hợp nhất ba tệp PDF 50 MB, bạn buộc phải tải lên 150 MB dữ liệu. Sau đó bạn đợi máy chủ của họ xử lý nó. Sau đó bạn tải về kết quả 150MB. Đó là một nút cổ chai mạng 300 MB. HandleMyFile xử lý 150 MB ngay lập tức trên ổ đĩa cục bộ của bạn bằng WebAssembly.',
