    pageCompareSec4Desc: 'Nhiều công cụ PDF trực tuyến có quyền quét các tài liệu đã tải lên của bạn. Kiến trúc ngoại tuyến của chúng tôi đảm bảo quyền riêng tư theo mặc định và miễn phí. Các tập tin của bạn không bao giờ rời khỏi thiết bị của bạn.',
