    footerUseCases: '사용 사례',
    pageUseCasesHero: '모든 직업을 위해 제작됨',
    pageUseCasesHeroSub: '엄격한 법률 환경부터 크리에이티브 에이전시까지 전문가들이 당사의 클라이언트측 처리 아키텍처를 신뢰하는 이유를 알아보세요.',
    pageUseCasesBadge: '산업 솔루션',
    pageUseCasesSec2Title: '법률 및 법률 회사',
    pageUseCasesSec2Desc: '변호사는 기밀이 높은 NDA, 계약 및 법원 서류를 처리합니다. 이러한 문서를 임의의 클라우드 API에 업로드하는 것은 큰 책임입니다. HandleMyFile을 사용하면 법무팀은 PDF 사례 파일을 완전히 오프라인으로 수정, 병합 및 분할하여 절대적인 고객 기밀을 보장할 수 있습니다.',
    pageUseCasesSec3Title: '인적 자원(HR)',
    pageUseCasesSec3Desc: 'HR 부서는 매일 PII(개인 식별 정보)를 처리합니다. ID 스캔, 급여 스프레드시트 처리, 제안서 관리에는 엄격한 GDPR/CCPA 준수가 필요합니다. HandleMyFile을 사용하면 HR 전문가가 내부 IT 보안 정책을 위반하지 않고 이러한 파일을 관리할 수 있습니다.',
    pageUseCasesSec4Title: '학생 및 교육',
    pageUseCasesSec4Desc: '학생들은 그룹 프로젝트 과제를 병합하거나 대학 포털의 5MB 업로드 제한에 맞게 프레젠테이션을 압축하기 위해 월 20달러를 지불할 필요가 없습니다. HandleMyFile은 파일 크기 제한 없이 프리미엄 도구에 대한 무제한 액세스를 무료로 제공합니다.',
    pageUseCasesSec5Title: '부동산 및 중개인',
    pageUseCasesSec5Desc: '부동산 중개인은 고객에게 이메일로 보내기에는 너무 큰 고해상도 이미지로 가득 찬 대규모 부동산 브로셔를 처리합니다. 또한 부동산 계획에 워터마크를 신속하게 표시하고 임대 계약에 서명해야 합니다. HandleMyFile은 100MB 이상의 파일을 즉시 처리합니다.',
    pageUseCasesSec6Title: '나만의 사용 사례 찾기',
    pageUseCasesSec6Desc: '업종에 관계없이 문서 작업을 하는 경우 HandleMyFile은 작업을 완료하는 가장 안전하고 빠른 방법입니다. 지금 20개 이상의 도구로 구성된 전체 제품군을 사용해 보세요.',
