    pageCompareHeroSub: '파일이 업로드되기를 기다리는 데 지치셨나요? 5MB 파일 제한으로 인해 좌절하셨나요? 전문가들이 클라이언트 측 문서 도구로 전환하는 이유를 알아보세요.',
