    zeroUploadDetails: '개인 문서를 원격 서버에 업로드하는 기존 클라우드 변환기와 달리 당사 플랫폼은 브라우저 RAM 내에서 직접 C/C++ WebAssembly 엔진을 실행합니다. 귀하의 기밀 문서는 절대로 인터넷을 통과하지 않습니다.',
