    privacyTitle: '절대적인 제로 업로드 보안',
    privacyText: '기업의 법적 개인 정보 보호 요구 사항(GDPR/HIPAA)을 준수합니다. 서버 저장, 데이터 로깅, 인위적인 제한이 없습니다.',
    pageAboutSec1Title: '기원 이야기',
    pageAboutSec1Desc: '우리는 전통적인 온라인 문서 도구의 지속적인 페이월과 개인정보 유출로 인해 좌절감을 느꼈습니다. 민감한 파일을 임의의 서버에 업로드하는 것은 본질적으로 잘못된 것으로 느껴졌습니다. 우리는 엔터프라이즈급 도구가 무료이고 빠르며 완벽하게 안전할 수 있음을 증명하기 위해 HandleMyFile을 구축했습니다.',
    pageAboutSec2Title: '기술 스택',
    pageAboutSec2Desc: 'WebAssembly(Wasm)의 강력한 기능을 활용하여 복잡한 서버 측 C++ 및 Rust 라이브러리를 가져와 웹 브라우저 내에서 직접 실행되도록 포팅했습니다. 즉, 서버가 귀하의 장치로 이동되므로 네트워크 업로드가 전혀 필요하지 않습니다.',
    pageAboutSec3Title: '우리의 보증',
    pageAboutSec3Desc: 'HandleMyFile은 완전 무료로 유지되도록 제작되었습니다. 우리의 임무는 모든 사람이 어디서나 문서 유틸리티를 민주화하는 것입니다.',
    pageAboutSec4Title: '운동에 동참하세요',
    pageAboutSec4Desc: '우리는 이 프로젝트를 계속 유지하기 위해 커뮤니티에 의존하고 있습니다. HandleMyFile을 친구, 가족, 동료와 공유하세요. 함께라면 우리는 더 안전하고, 더 빠르고, 더 접근하기 쉬운 웹을 구축할 수 있습니다.',
    pagePrivacySec1Title: '데이터 처리 매트릭스',
    pagePrivacySec1Desc: '우리는 IP 주소를 수집하지 않습니다. 우리는 귀하의 파일을 저장하지 않습니다. 우리는 이메일 등록을 요구하지 않습니다. 문서 데이터의 모든 비트는 항상 물리적 장치에만 남아 있습니다.',
    pagePrivacySec2Title: '클라이언트측 작동 방식',
    pagePrivacySec2Desc: 'HandleMyFile에서 파일을 선택하면 해당 파일이 브라우저의 RAM에 직접 로드됩니다. WebAssembly 엔진은 파일을 로컬로 처리하고 메모리에서 직접 다운로드하라는 메시지를 표시합니다. 파일은 인터넷을 통해 이동하지 않습니다.',
    pagePrivacySec3Title: '타사 통합',
    pagePrivacySec3Desc: '우리는 매우 독립적입니다. 우리는 귀하의 개인정보를 침해할 수 있는 숨겨진 분석 추적기, 광고 네트워크 또는 제3자 쿠키를 포함하지 않습니다. HandleMyFile에서 발생하는 일은 HandleMyFile에 유지됩니다.',
    pagePrivacySec4Title: '글로벌 규정 준수',
    pagePrivacySec4Desc: '당사의 아키텍처는 수학적으로 귀하의 파일에 액세스하는 것을 방지하기 때문에 HandleMyFile은 본질적으로 GDPR, CCPA 및 기타 글로벌 데이터 보호 규정의 개인 정보 보호 요구 사항을 초과합니다.',
    pageTosSec1Title: '허용되는 사용 정책',
    pageTosSec1Desc: '귀하는 합법적인 목적으로만 HandleMyFile을 사용하는 데 동의합니다. 귀하는 법률 문서, 정부 ID 또는 사기 행위를 위한 자료를 위조, 조작 또는 위조하는 데 당사의 도구를 사용해서는 안 됩니다.',
    pageTosSec2Title: '지적재산권',
    pageTosSec2Desc: '귀하는 HandleMyFile을 사용하여 처리하는 문서에 대한 100% 소유권과 모든 지적 재산권을 보유합니다. 우리는 귀하의 콘텐츠에 대해 어떠한 권리, 라이센스 또는 소유권도 주장하지 않습니다.',
    pageTosSec3Title: '서비스 수정',
    pageTosSec3Desc: '당사는 사전 통지 없이 언제든지 서비스의 일부를 수정, 일시 중지 또는 중단할 권리를 보유합니다. 완전한 클라이언트 측 플랫폼으로서 우리는 모든 브라우저 버전과의 호환성을 보장할 수 없습니다.',
    pageTosSec4Title: '책임의 제한',
    pageTosSec4Desc: '어떠한 경우에도 HandleMyFile, 작성자 또는 기여자는 당사 도구의 사용 또는 사용 불가능으로 인해 발생하는 직접적, 간접적, 우발적 또는 결과적 손해에 대해 책임을 지지 않습니다.',
  
    homeGeoDefTitle: 'HandleMyFile이란 무엇입니까?',
    homeGeoDefDesc: 'HandleMyFile은 사용자가 브라우저에서 직접 PDF 및 Office 파일을 편집, 변환, 병합 및 압축할 수 있는 100% 클라이언트 측 문서 처리 응용 프로그램입니다. WebAssembly(WASM)를 활용하면 외부 서버에 아무것도 업로드하지 않고 장치에서 로컬로 모든 데이터를 처리하여 절대적인 개인정보 보호와 엔터프라이즈급 보안을 보장합니다.',
    homeGeoTrustTitle: '이것이 100% 안전하고 비공개인 이유는 무엇입니까?',
    homeGeoTrustDesc: '민감한 문서를 서버에 업로드해야 하는 기존 클라우드 기반 PDF 도구와 달리 HandleMyFile은 브라우저의 보안 샌드박스 내에서 모든 알고리즘을 실행합니다. 애플리케이션은 WebAssembly 및 JavaScript TypedArray를 사용하여 파일을 로컬에서 조작합니다. 이 아키텍처는 데이터 유출이 없음을 보장합니다.',
    homeGeoTakeawaysTitle: '주요 시사점',
    homeGeoTakeawaysItem1: 'PDF 및 Office 파일을 브라우저 메모리에서 로컬로 처리하세요.',
    homeGeoTakeawaysItem2: '파일 업로드가 필요하지 않아 전체 데이터 개인정보 보호가 보장됩니다.',
    homeGeoTakeawaysItem3: '고속 오프라인 변환을 위해 WebAssembly로 구동됩니다.',
    homeGeoFaqTitle: '자주 묻는 질문',
    homeGeoFaq1Q: 'HandleMyFile은 서버 없이 어떻게 작동하나요?',
    homeGeoFaq1A: 'WebAssembly(WASM)를 활용하여 웹 브라우저 엔진 내에서 직접 무거운 C++ 및 Rust 처리 라이브러리를 실행합니다.',
    homeGeoFaq2Q: '파일 크기 제한이 있나요?',
    homeGeoFaq2A: '아니요. 처리는 로컬 장치에서 이루어지기 때문에 유일한 제한은 컴퓨터의 사용 가능한 RAM입니다.',
    homeGeoFaq3Q: '회사 기밀 문서에 안전한가요?',
    homeGeoFaq3A: '예, 이것이 가장 안전한 방법입니다. 파일은 절대 장치를 떠나지 않으며 인터넷을 통해 전송되지 않습니다.',
