    footerPricing: 'Wycena',
    pagePricingHero: 'Zero subskrypcji. Zerowe limity.',
    pagePricingHeroSub: 'Narzędzia do obsługi dokumentów klasy korporacyjnej zwykle kosztują 20 USD miesięcznie. Wierzymy, że prywatność i użyteczność powinny być podstawowym prawem człowieka. HandleMyFile jest całkowicie darmowy.',
    pagePricingBadge: 'Radykalnie bezpłatny',
    pagePricingComp: 'Tradycyjne narzędzia w chmurze',
    pagePricingSec3Title: 'Jak to możliwe?',
    pagePricingSec3Desc: 'Tradycyjne narzędzia wiążą się z wysokimi rachunkami za serwer, ponieważ przetwarzają Twoje pliki w chmurze. Przenieśliśmy silniki C++ i Rust, aby działały w przeglądarce. Twój komputer wykonuje ciężką pracę, co oznacza, że ​​koszty naszego serwera są bliskie zeru. Przekazujemy te oszczędności bezpośrednio Tobie.',
    pagePricingSec4Title: 'Zrównoważony i przejrzysty',
    pagePricingSec4Desc: 'Aby HandleMyFile był zawsze w 100% darmowy, polegamy na nieinwazyjnych reklamach i standardowych analitykach sieciowych. Jednak Twoja prywatność jest dla nas najwyższym priorytetem. Nigdy nie skanujemy, nie wyodrębniamy ani nie sprzedajemy zawartości Twoich plików. Co dzieje się w edytorze, zostaje w edytorze.',
    pagePricingSec5Title: 'Bezpłatnie do użytku biznesowego',
    pagePricingSec5Desc: 'Tak, możesz używać HandleMyFile w swojej firmie. W rzeczywistości nasza lokalna architektura przetwarzania czyni nas jedyną platformą wystarczająco bezpieczną dla rygorystycznych środowisk korporacyjnych, zespołów prawnych i pracowników służby zdrowia.',
    pagePricingSec6Title: 'Wesprzyj projekt',
    pagePricingSec6Desc: 'Nie pobieramy abonamentu, ale utrzymanie domeny i jej rozwój wymaga czasu. Jeśli HandleMyFile uratował Twój dzień, rozważ udostępnienie go swojemu zespołowi. Poczta pantoflowa to nasza jedyna strategia marketingowa.',
    shareBtn: 'Udostępnij HandleMyFile',
    footerSecurity: 'Bezpieczeństwo i zaufanie',
    pageSecurityHero: 'Prywatność matematyczna. Zero przesyłania.',
    pageSecurityHeroSub: 'Większość narzędzi do obsługi dokumentów obiecuje, że usunie Twoje pliki po 1 godzinie. Obiecujemy, że nigdy nie zobaczymy Twoich plików.',
    pageSecurityBadge: 'Centrum zaufania',
    pageSecuritySec2Title: 'Rewolucja w zakresie WebAssembly',
    pageSecuritySec3Title: 'Twoje dokumenty są dla nas niewidoczne',
    pageSecuritySec3Desc: 'Chociaż używamy standardowych analiz w celu poprawy komfortu korzystania z naszej witryny, nasze skrypty nigdy nie mają wpływu na Twoje dokumenty. Nie wyodrębniamy metadanych, treści tekstowych ani obrazów. Piaskownica do przetwarzania dokumentów jest całkowicie niezależna na karcie przeglądarki.',
    pageSecuritySec4Title: 'Domyślna zgodność',
    pageSecuritySec4Desc: 'Ponieważ HandleMyFile nie może uzyskać dostępu do Twoich plików, korzystanie z naszych narzędzi automatycznie spełnia najsurowsze przepisy dotyczące ochrony danych na całym świecie.',
    pageSecuritySec5Title: 'Nie ufaj nam. Zweryfikuj to.',
    pageSecuritySec5Desc: 'Nie musisz nam wierzyć na słowo. Możesz sam udowodnić naszą gwarancję offline w 3 prostych krokach:',
    pageSecuritySec6Title: 'Przyszłość jest lokalna',
    pageSecuritySec6Desc: 'Wyobrażamy sobie sieć, w której aplikacje narzędziowe szanują Twój sprzęt i Twoją prywatność. Witamy w nowej erze przetwarzania po stronie klienta.',
    footerAbout: 'O nás',
