    compareTr7Col3: 'Okamžité (místní CPU)',
    pageCompareExpertTitle: 'Vytvořeno pro soukromí',
    pageCompareExpertQuote: 'Nahrávání důvěrných firemních dokumentů do cloudových rozhraní API může být pro vzdálené týmy zranitelností. Nástroje pro zpracování na straně klienta, jako je HandleMyFile, poskytují architekturu s nulovou důvěryhodností vhodnou pro místní zpracování citlivých souborů PDF.',
    pageCompareExpertRole: 'Privacy by Design',
    footerCompany: 'Selskab',
    footerLanguages: 'Understøttede sprog',
    pageCompareSec3Desc: 'Med ældre cloud-værktøjer er du tvunget til at uploade 150 MB data, hvis du vil flette tre 50 MB PDF-filer. Så venter du på, at deres server behandler det. Så downloader du resultatet på 150MB. Det er en 300 MB netværksflaskehals. HandleMyFile behandler de 150 MB øjeblikkeligt på din lokale disk ved hjælp af WebAssembly.',
    pageCompareSec4Title: 'Hold dine data private',
    pageCompareSec4Desc: 'Mange online PDF-værktøjer forbeholder sig retten til at scanne dine uploadede dokumenter. Vores offline arkitektur garanterer privatliv som standard, gratis. Dine filer forlader aldrig din enhed.',
    pageCompareSec5Title: 'Undslippe filstørrelsesfælden',
    pageCompareSec5Desc: 'Cloud API\'er begrænser ofte din arbejdsgang med grænser på 5 MB. HandleMyFile bruger din enheds RAM, hvilket betyder, at du kan behandle 1GB+ filer lokalt, hvis din computer kan håndtere det.',
    pageCompareSec6Title: 'Skift i dag',
    pageCompareSec6Desc: 'Stop med at gå på kompromis med hastighed, privatliv og omkostninger. Slut dig til tusindvis af fagfolk, der allerede har skiftet til det hurtigste offline dokumentværktøjssæt på nettet.',
    pageLangHero: 'Understøttede sprog',
    pageLangHeroSub: 'HandleMyFile er fuldt lokaliseret på 30 sprog.',
    pageLangBadge: 'Global adgang',
    pageLangSec2Title: 'Indfødt lokalisering',
    pageLangSec3Title: 'Bryd sprogbarrierer',
    pageLangSec3Desc: 'Brug vores offline dokumentværktøjer på dit modersmål. Vi understøtter venstre-til-højre- og højre-til-venstre-sprog med fuld UI-lokalisering.',
    pageLangSec4Title: 'Ingen cloud-oversættelse nødvendig',
    pageLangSec4Desc: 'Al UI-tekst er bundtet direkte i applikationen, hvilket betyder, at du ikke behøver internetadgang for at skifte sprog.',
    pageLangSec5Title: 'Sømløs skift',
    pageLangSec5Desc: 'Skift sprog med det samme uden at genindlæse applikationen.',
    pageLangSec6Title: 'Klar til at starte?',
    pageLangSec6Desc: 'Vælg dit foretrukne sprog, og oplev de hurtigste offline dokumentværktøjer på nettet.',
    footerUseCases: 'Przypadki użycia',
    pageUseCasesHero: 'Zbudowany dla każdego zawodu',
    pageUseCasesHeroSub: 'Od rygorystycznych środowisk prawnych po agencje kreatywne – odkryj, dlaczego profesjonaliści ufają naszej architekturze przetwarzania po stronie klienta.',
    pageUseCasesBadge: 'Rozwiązania branżowe',
    pageUseCasesSec2Title: 'Prawnicy i kancelarie prawne',
    pageUseCasesSec2Desc: 'Prawnicy zajmują się wysoce poufnymi umowami NDA, umowami i pismami sądowymi. Przesyłanie tych dokumentów do losowych interfejsów API w chmurze wiąże się z dużą odpowiedzialnością. Dzięki HandleMyFile zespoły prawne mogą redagować, łączyć i dzielić pliki spraw w formacie PDF całkowicie w trybie offline, zapewniając całkowitą poufność klienta.',
    pageUseCasesSec3Title: 'Zasoby ludzkie (HR)',
    pageUseCasesSec3Desc: 'Działy HR na co dzień zajmują się danymi osobowymi (PII, czyli danymi osobowymi). Skanowanie identyfikatorów, obsługa arkuszy kalkulacyjnych płac i zarządzanie listami ofertowymi wymaga ścisłej zgodności z RODO/CCPA. HandleMyFile pozwala specjalistom HR zarządzać tymi plikami bez naruszania wewnętrznych zasad bezpieczeństwa IT.',
    pageUseCasesSec4Title: 'Studenci i edukacja',
    pageUseCasesSec4Desc: 'Studenci nie powinni płacić 20 dolarów miesięcznie za samo połączenie zadań z projektów grupowych lub skompresowanie prezentacji tak, aby zmieściła się w 5 MB limitu przesyłania na portalu uniwersyteckim. HandleMyFile zapewnia nieograniczony dostęp do narzędzi premium za darmo, z zerowymi limitami rozmiaru pliku.',
    pageUseCasesSec5Title: 'Nieruchomości i agenci',
    pageUseCasesSec5Desc: 'Agenci nieruchomości obsługują ogromne broszury dotyczące nieruchomości, wypełnione obrazami o wysokiej rozdzielczości, które są zbyt duże, aby wysłać je pocztą elektroniczną do klientów. Muszą także szybko znakować plany nieruchomości i podpisywać umowy najmu. HandleMyFile natychmiast obsługuje pliki o wielkości ponad 100 MB.',
    pageUseCasesSec6Title: 'Znajdź swój własny przypadek użycia',
    pageUseCasesSec6Desc: 'Bez względu na branżę, jeśli pracujesz z dokumentami, HandleMyFile to najbezpieczniejszy i najszybszy sposób na wykonanie zadania. Wypróbuj nasz pełny zestaw ponad 20 narzędzi już dziś.',
    footerCompare: 'Porównywać',
    pageCompareHero: 'HandleMyFile kontra reszta',
    pageCompareHeroSub: 'Masz dość czekania na przesłanie plików? Sfrustrowany limitem plików wynoszącym 5 MB? Dowiedz się, dlaczego profesjonaliści przechodzą na narzędzia do obsługi dokumentów po stronie klienta.',
