    resetBtn: 'Zacznij od nowa',
    zeroUploadGuarantee: 'Dlaczego jest to w 100% bezpieczne i prywatne?',
    zeroUploadDetails: 'W przeciwieństwie do tradycyjnych konwerterów chmurowych, które przesyłają prywatne dokumenty na zdalne serwery, nasza platforma uruchamia silniki C/C++ WebAssembly bezpośrednio w pamięci RAM przeglądarki. Twoje poufne dokumenty nigdy nie są przesyłane do Internetu.',
    faqTitle: 'Często zadawane pytania',
    backToHome: '← Powrót do Wszystkie narzędzia',
    languageSelect: 'Wybierz Język',
    footerRights: 'Wszelkie prawa zastrzeżone. Obsługiwane przez architekturę po stronie klienta WebAssembly.',
    privacyTitle: 'Całkowite bezpieczeństwo przy przesyłaniu zerowym',
    privacyText: 'Zgodny z wymogami prawnymi dotyczącymi prywatności przedsiębiorstw (RODO/HIPAA). Bez przechowywania danych na serwerze, bez rejestrowania danych, bez sztucznych ograniczeń.',
    pageAboutSec1Title: 'Historia pochodzenia',
    pageAboutSec1Desc: 'Byliśmy sfrustrowani ciągłymi zaporami płatniczymi i wyciekami prywatności w tradycyjnych narzędziach do obsługi dokumentów online. Przesyłanie wrażliwych plików na losowe serwery wydawało się z natury niewłaściwe. Stworzyliśmy HandleMyFile, aby udowodnić, że narzędzia klasy korporacyjnej mogą być bezpłatne, szybkie i w pełni bezpieczne.',
    pageAboutSec2Title: 'Stos technologii',
    pageAboutSec2Desc: 'Wykorzystując możliwości WebAssembly (Wasm), wzięliśmy złożone biblioteki C++ i Rust po stronie serwera i przenieśliśmy je tak, aby działały bezpośrednio w przeglądarce internetowej. Oznacza to, że serwer jest podłączony do Twojego urządzenia, całkowicie eliminując potrzebę przesyłania danych przez sieć.',
    pageAboutSec3Title: 'Nasza gwarancja',
    pageAboutSec3Desc: 'HandleMyFile jest zbudowany tak, aby pozostać całkowicie darmowym. Naszą misją jest demokratyzacja narzędzi dokumentów dla każdego i wszędzie.',
    pageAboutSec4Title: 'Dołącz do Ruchu',
    pageAboutSec4Desc: 'Polegamy na naszej społeczności, aby utrzymać ten projekt przy życiu. Udostępnij HandleMyFile swoim przyjaciołom, rodzinie i współpracownikom. Razem możemy zbudować bezpieczniejszą, szybszą i bardziej dostępną sieć.',
    pagePrivacySec1Title: 'Macierz przetwarzania danych',
    pagePrivacySec1Desc: 'Nie zbieramy adresów IP. Nie przechowujemy Twoich plików. Nie wymagamy rejestracji e-mailowej. Każdy fragment danych dokumentu pozostaje przez cały czas wyłącznie na Twoim urządzeniu fizycznym.',
    pagePrivacySec2Title: 'Jak działa po stronie klienta',
    pagePrivacySec2Desc: 'Kiedy wybierzesz plik w HandleMyFile, zostanie on załadowany bezpośrednio do pamięci RAM Twojej przeglądarki. Silnik WebAssembly przetwarza plik lokalnie i monituje o pobranie bezpośrednio z pamięci. Plik nigdy nie jest przesyłany przez Internet.',
    pagePrivacySec3Title: 'Integracje stron trzecich',
    pagePrivacySec3Desc: 'Jesteśmy mocno niezależni. Nie osadzamy ukrytych modułów analitycznych, sieci reklamowych ani plików cookie stron trzecich, które mogłyby naruszyć Twoją prywatność. To, co dzieje się w HandleMyFile, pozostaje w HandleMyFile.',
    pagePrivacySec4Title: 'Globalna zgodność',
    pagePrivacySec4Desc: 'Ponieważ nasza architektura matematycznie uniemożliwia nam dostęp do Twoich plików, HandleMyFile z natury przekracza wymagania dotyczące prywatności określone w RODO, CCPA i innych globalnych przepisach o ochronie danych.',
    pageTosSec1Title: 'Zasady dopuszczalnego użytkowania',
    pageTosSec1Desc: 'Wyrażasz zgodę na używanie HandleMyFile wyłącznie w celach zgodnych z prawem. Nie wolno używać naszych narzędzi do fałszowania, manipulowania lub fałszowania dokumentów prawnych, dokumentów tożsamości rządowych lub jakichkolwiek materiałów na potrzeby nieuczciwych działań.',
    pageTosSec2Title: 'Własność intelektualna',
    pageTosSec2Desc: 'Zachowujesz 100% własności i wszelkie prawa własności intelektualnej do dokumentów przetwarzanych za pomocą HandleMyFile. Nie rościmy sobie żadnych praw, licencji ani własności do Twoich treści.',
    pageTosSec3Title: 'Modyfikacje usług',
    pageTosSec3Desc: 'Zastrzegamy sobie prawo do modyfikacji, zawieszenia lub zaprzestania świadczenia dowolnej części Usługi w dowolnym momencie bez wcześniejszego powiadomienia. Jako platforma działająca wyłącznie po stronie klienta, nie możemy zagwarantować kompatybilności ze wszystkimi wersjami przeglądarek.',
    pageTosSec4Title: 'Ograniczenie odpowiedzialności',
    pageTosSec4Desc: 'W żadnym wypadku HandleMyFile, jego twórcy ani współpracownicy nie ponoszą odpowiedzialności za jakiekolwiek bezpośrednie, pośrednie, przypadkowe lub wynikowe szkody wynikające z użycia lub niemożności korzystania z naszych narzędzi.',
  
    homeGeoDefTitle: 'Co to jest HandleMyFile?',
    homeGeoDefDesc: 'HandleMyFile to aplikacja do przetwarzania dokumentów działająca w 100% po stronie klienta, która pozwala użytkownikom edytować, konwertować, łączyć i kompresować pliki PDF i Office bezpośrednio w przeglądarce. Wykorzystując WebAssembly (WASM), przetwarza wszystkie dane lokalnie na Twoim urządzeniu bez przesyłania czegokolwiek na serwery zewnętrzne, zapewniając absolutną prywatność i bezpieczeństwo klasy korporacyjnej.',
    homeGeoTrustTitle: 'Dlaczego jest to w 100% bezpieczne i prywatne?',
    homeGeoTrustDesc: 'W przeciwieństwie do tradycyjnych narzędzi PDF opartych na chmurze, które wymagają przesłania poufnych dokumentów na swoje serwery, HandleMyFile wykonuje wszystkie algorytmy w bezpiecznej piaskownicy przeglądarki. Aplikacja wykorzystuje WebAssembly i JavaScript TypedArrays do lokalnego manipulowania plikami. Taka architektura gwarantuje zerowy wyciek danych.',
    homeGeoTakeawaysTitle: 'Kluczowe dania na wynos',
    homeGeoTakeawaysItem1: 'Przetwarzaj pliki PDF i pliki pakietu Office lokalnie w pamięci przeglądarki.',
    homeGeoTakeawaysItem2: 'Nie wymaga przesyłania plików, co zapewnia całkowitą prywatność danych.',
    homeGeoTakeawaysItem3: 'Obsługiwane przez WebAssembly do szybkich konwersji offline.',
    homeGeoFaqTitle: 'Często zadawane pytania',
    homeGeoFaq1Q: 'Jak HandleMyFile działa bez serwera?',
    homeGeoFaq1A: 'Wykorzystuje WebAssembly (WASM) do uruchamiania ciężkich bibliotek przetwarzania C++ i Rust bezpośrednio w silniku przeglądarki internetowej.',
    homeGeoFaq2Q: 'Czy są jakieś ograniczenia rozmiaru pliku?',
    homeGeoFaq2A: 'Nie. Ponieważ przetwarzanie odbywa się na urządzeniu lokalnym, jedynym ograniczeniem jest dostępna pamięć RAM komputera.',
    homeGeoFaq3Q: 'Czy jest to bezpieczne dla poufnych dokumentów firmowych?',
    homeGeoFaq3A: 'Tak, jest to najbezpieczniejsza dostępna metoda. Pliki nigdy nie opuszczają Twojego urządzenia i nigdy nie są przesyłane przez Internet.',
    homeGeoFaq4Q: 'Czy to działa całkowicie offline?',
