    footerPricing: 'Định giá',
    pagePricingHero: 'Không đăng ký. Không có giới hạn.',
    pagePricingHeroSub: 'Các công cụ tài liệu cấp doanh nghiệp thường có giá 20 USD/tháng. Chúng tôi tin rằng quyền riêng tư và tiện ích phải là quyền cơ bản của con người. HandleMyFile hoàn toàn miễn phí.',
