    pagePricingSec3Title: 'Làm thế nào điều này có thể xảy ra?',
    pagePricingSec3Desc: 'Các công cụ truyền thống có chi phí máy chủ đắt đỏ vì chúng xử lý tệp của bạn trên đám mây của chúng. Chúng tôi đã chuyển các công cụ C++ và Rust để chạy bên trong trình duyệt của bạn. Máy tính của bạn đảm nhận công việc nặng nhọc, nghĩa là chi phí máy chủ của chúng tôi gần bằng 0. Chúng tôi chuyển những khoản tiết kiệm đó trực tiếp cho bạn.',
    pagePricingSec4Title: 'Bền vững & Minh bạch',
    pagePricingSec4Desc: 'Để giữ cho HandleMyFile miễn phí 100% mãi mãi, chúng tôi dựa vào các quảng cáo không xâm phạm và phân tích trang web tiêu chuẩn. Tuy nhiên, quyền riêng tư của bạn là ưu tiên hàng đầu của chúng tôi. Chúng tôi không bao giờ quét, trích xuất hoặc bán nội dung tệp của bạn. Điều gì xảy ra trong trình chỉnh sửa sẽ vẫn ở trong trình chỉnh sửa.',
    pagePricingSec5Title: 'Miễn phí cho việc sử dụng kinh doanh',
    pagePricingSec5Desc: 'Có, bạn có thể sử dụng HandleMyFile cho công ty của mình. Trên thực tế, kiến ​​trúc xử lý cục bộ của chúng tôi giúp chúng tôi trở thành nền tảng duy nhất đủ an toàn cho các môi trường doanh nghiệp, nhóm pháp lý và chuyên gia chăm sóc sức khỏe nghiêm ngặt.',
    pagePricingSec6Title: 'Hỗ trợ dự án',
    pagePricingSec6Desc: 'Chúng tôi không tính phí đăng ký nhưng việc duy trì miền và quá trình phát triển cần có thời gian. Nếu HandleMyFile đã giúp ích cho bạn một ngày, hãy cân nhắc việc chia sẻ nó với nhóm của bạn. Truyền miệng là chiến lược tiếp thị duy nhất của chúng tôi.',
