    compareTr7Col3: 'Instant (Τοπική CPU)',
    pageCompareExpertTitle: 'Κατασκευάστηκε για την προστασία της ιδιωτικής ζωής',
    pageCompareExpertQuote: 'Η μεταφόρτωση εμπιστευτικών εταιρικών εγγράφων σε API cloud μπορεί να είναι μια ευπάθεια για τις απομακρυσμένες ομάδες. Τα εργαλεία επεξεργασίας από την πλευρά του πελάτη, όπως το HandleMyFile, παρέχουν μια αρχιτεκτονική μηδενικής εμπιστοσύνης, κατάλληλη για τοπικό χειρισμό ευαίσθητων αρχείων PDF.',
    pageCompareExpertRole: 'Privacy by Design',
    pageCompareSec3Desc: 'Με τα εργαλεία cloud παλαιού τύπου, εάν θέλετε να συγχωνεύσετε τρία αρχεία PDF των 50 MB, αναγκάζεστε να ανεβάσετε 150 MB δεδομένων. Στη συνέχεια, περιμένετε να το επεξεργαστεί ο διακομιστής τους. Στη συνέχεια κατεβάζετε το αποτέλεσμα των 150 MB. Αυτό είναι ένα σημείο συμφόρησης δικτύου 300 MB. Το HandleMyFile επεξεργάζεται τα 150 MB άμεσα στον τοπικό σας δίσκο χρησιμοποιώντας το WebAssembly.',
    pageCompareSec4Title: 'Διατηρήστε τα δεδομένα σας απόρρητα',
    pageCompareSec4Desc: 'Πολλά διαδικτυακά εργαλεία PDF διατηρούν το δικαίωμα να σαρώσουν τα μεταφορτωμένα έγγραφά σας. Η αρχιτεκτονική μας εκτός σύνδεσης εγγυάται το απόρρητο από προεπιλογή, δωρεάν. Τα αρχεία σας δεν φεύγουν ποτέ από τη συσκευή σας.',
    pageCompareSec5Title: 'Αποδράστε από την παγίδα μεγέθους αρχείου',
    pageCompareSec5Desc: 'Τα API του cloud συχνά περιορίζουν τη ροή εργασίας σας με όρια 5 MB. Το HandleMyFile χρησιμοποιεί τη μνήμη RAM της συσκευής σας, που σημαίνει ότι μπορείτε να επεξεργαστείτε αρχεία 1 GB+ τοπικά, εάν ο υπολογιστής σας μπορεί να το χειριστεί.',
    pageCompareSec6Title: 'Switch Today',
    pageCompareSec6Desc: 'Σταματήστε να συμβιβάζεστε με την ταχύτητα, το απόρρητο και το κόστος. Γίνετε μέλος χιλιάδων επαγγελματιών που έχουν ήδη μεταβεί στην ταχύτερη εργαλειοθήκη εγγράφων εκτός σύνδεσης στον ιστό.',
    pageLangHero: 'Υποστηριζόμενες γλώσσες',
    pageLangHeroSub: 'Το HandleMyFile είναι πλήρως προσαρμοσμένο σε 30 γλώσσες.',
