    pageLangSec3Desc: 'Χρησιμοποιήστε τα εργαλεία εγγράφων εκτός σύνδεσης στη μητρική σας γλώσσα. Υποστηρίζουμε γλώσσες από αριστερά προς τα δεξιά και από δεξιά προς τα αριστερά με πλήρη προσαρμογή διεπαφής χρήστη.',
    pageLangSec4Title: 'Δεν απαιτείται μετάφραση στο Cloud',
