    pageUseCasesHeroSub: 'Từ môi trường pháp lý nghiêm ngặt đến các đại lý sáng tạo, hãy khám phá lý do tại sao các chuyên gia lại tin tưởng vào kiến ​​trúc xử lý phía khách hàng của chúng tôi.',
    pageUseCasesBadge: 'Giải pháp ngành',
    pageUseCasesSec2Title: 'Công ty luật & pháp lý',
    pageUseCasesSec2Desc: 'Luật sư xử lý NDA, hợp đồng và hồ sơ tòa án có tính bảo mật cao. Tải những tài liệu này lên API đám mây ngẫu nhiên là một trách nhiệm lớn. Với HandleMyFile, các nhóm pháp lý có thể sắp xếp lại, hợp nhất và phân chia các tệp vụ việc PDF hoàn toàn ngoại tuyến, đảm bảo tính bảo mật tuyệt đối của khách hàng.',
    pageUseCasesSec3Title: 'Nhân sự (HR)',
    pageUseCasesSec3Desc: 'Bộ phận nhân sự xử lý PII (Thông tin nhận dạng cá nhân) hàng ngày. Việc quét ID, xử lý bảng tính bảng lương và quản lý thư mời làm việc yêu cầu phải tuân thủ nghiêm ngặt GDPR/CCPA. HandleMyFile cho phép các chuyên gia nhân sự quản lý các tệp này mà không vi phạm chính sách bảo mật CNTT nội bộ.',
    pageUseCasesSec4Title: 'Sinh viên & Giáo dục',
    pageUseCasesSec4Desc: 'Sinh viên không phải trả $20/tháng chỉ để hợp nhất các bài tập dự án nhóm của họ hoặc nén bài thuyết trình để phù hợp với giới hạn tải lên 5MB của cổng thông tin đại học. HandleMyFile cung cấp quyền truy cập miễn phí không giới hạn vào các công cụ cao cấp, không giới hạn kích thước tệp.',
    pageUseCasesSec5Title: 'Bất động sản & Đại lý',
    pageUseCasesSec5Desc: 'Các đại lý bất động sản xử lý các tài liệu quảng cáo bất động sản khổng lồ chứa đầy hình ảnh có độ phân giải cao, quá lớn để gửi email cho khách hàng. Họ cũng cần nhanh chóng đánh dấu các kế hoạch tài sản và ký hợp đồng cho thuê. HandleMyFile xử lý các tệp có dung lượng hơn 100 MB ngay lập tức.',
    pageUseCasesSec6Title: 'Tìm trường hợp sử dụng của riêng bạn',
    pageUseCasesSec6Desc: 'Bất kể ngành nghề của bạn là gì, nếu bạn làm việc với các tài liệu, HandleMyFile là cách an toàn nhất và nhanh nhất để hoàn thành công việc. Hãy thử bộ đầy đủ hơn 20 công cụ của chúng tôi ngay hôm nay.',
