    pageCompareExpertTitle: 'Rakennettu tietosuojaa varten',
    pageCompareExpertQuote: 'Luottamuksellisten yritysasiakirjojen lähettäminen pilvisovellusliittymiin voi olla haavoittuvuus etätiimeille. Asiakaspuolen käsittelytyökalut, kuten HandleMyFile, tarjoavat nollaluottamusarkkitehtuurin, joka sopii arkaluonteisten PDF-tiedostojen paikalliseen käsittelyyn.',
    pageCompareExpertRole: 'Yksityisyys suunnittelusta',
    pageCompareSec3Desc: 'Vanhojen pilvityökalujen avulla, jos haluat yhdistää kolme 50 Mt:n PDF-tiedostoa, sinun on lähetettävä 150 Mt tietoa. Sitten odotat, että heidän palvelimensa käsittelee sen. Sitten lataat 150 Mt:n tuloksen. Se on 300 megatavun verkon pullonkaula. HandleMyFile käsittelee 150 Mt paikallisella levylläsi välittömästi WebAssemblyn avulla.',
