    pageCompareSec4Desc: 'Monet online-PDF-työkalut varaavat oikeuden skannata lataamasi asiakirjat. Offline-arkkitehtuurimme takaa yksityisyyden oletuksena ilmaiseksi. Tiedostosi eivät koskaan poistu laitteestasi.',
    pageCompareSec5Title: 'Pakene tiedostokokoloukusta',
