    pageCompareSec3Desc: 'Az örökölt felhőeszközökkel, ha három 50 MB-os PDF-et szeretne egyesíteni, 150 MB adatot kell feltöltenie. Ezután várja meg, amíg a szerverük feldolgozza. Ezután letölti a 150 MB-os eredményt. Ez egy 300 MB-os hálózati szűk keresztmetszet. A HandleMyFile a 150 MB-ot azonnal feldolgozza a helyi lemezen a WebAssembly segítségével.',
    pageCompareSec4Title: 'Tartsa személyesen adatait',
    pageCompareSec4Desc: 'Számos online PDF-eszköz fenntartja a jogot a feltöltött dokumentumok szkennelésére. Offline architektúránk alapértelmezés szerint ingyenesen garantálja az adatvédelmet. A fájlok soha nem hagyják el az eszközt.',
