    pageCompareSec6Title: 'Váltson még ma',
    pageCompareSec6Desc: 'Hagyja abba a kompromisszumot a sebesség, a magánélet és a költségek terén. Csatlakozzon több ezer szakemberhez, akik már átváltottak az internet leggyorsabb offline dokumentum-eszközkészletére.',
