    pageUseCasesBadge: 'Industrilösningar',
    pageUseCasesSec2Title: 'Juridiska & Advokatbyråer',
    pageUseCasesSec2Desc: 'Advokater hanterar mycket konfidentiella NDAs, kontrakt och domstolshandlingar. Att ladda upp dessa dokument till slumpmässiga moln-API:er är ett stort ansvar. Med HandleMyFile kan juridiska team redigera, slå samman och dela PDF-ärendefiler helt offline, vilket säkerställer absolut klientsekretess.',
    pageUseCasesSec3Title: 'Human Resources (HR)',
    pageUseCasesSec3Desc: 'HR-avdelningar hanterar PII (Personally Identifiable Information) dagligen. Skanning av ID, hantering av lönekalkylblad och hantering av erbjudandebrev kräver strikt GDPR/CCPA-efterlevnad. HandleMyFile låter HR-proffs hantera dessa filer utan att bryta mot interna IT-säkerhetspolicyer.',
    pageUseCasesSec4Title: 'Studenter & Utbildning',
    pageUseCasesSec4Desc: 'Studenter ska inte behöva betala $20/månad bara för att slå samman sina gruppprojektuppgifter eller komprimera en presentation för att passa universitetsportalens uppladdningsgräns på 5 MB. HandleMyFile ger obegränsad tillgång till premiumverktyg gratis, med noll filstorleksgränser.',
    pageUseCasesSec5Title: 'Fastigheter & Mäklare',
    pageUseCasesSec5Desc: 'Fastighetsmäklare hanterar massiva fastighetsbroschyrer packade med högupplösta bilder som är för stora för att skicka e-post till kunder. De måste också snabbt vattenmärka fastighetsplaner och underteckna hyresavtal. HandleMyFile hanterar 100MB+ filer direkt.',
    pageUseCasesSec6Title: 'Hitta ditt eget användningsfall',
    pageUseCasesSec6Desc: 'Oavsett din bransch, om du arbetar med dokument är HandleMyFile det säkraste och snabbaste sättet att få jobbet gjort. Prova vår kompletta uppsättning av 20+ verktyg idag.',
