    zeroUploadDetails: 'Till skillnad från traditionella molnkonverterare som laddar upp dina privata dokument till fjärrservrar, kör vår plattform C/C++ WebAssembly-motorer direkt i webbläsarens RAM. Dina konfidentiella dokument går aldrig igenom internet.',
    faqTitle: 'Vanliga frågor',
    backToHome: '← Tillbaka till Alla verktyg',
