    privacyTitle: 'Absolut noll-uppladdningssäkerhet',
    privacyText: 'Överensstämmer med företagets juridiska integritetskrav (GDPR/HIPAA). Ingen serverlagring, ingen dataloggning, inga konstgjorda gränser.',
    pageAboutSec1Title: 'Ursprungsberättelsen',
    pageAboutSec1Desc: 'Vi var frustrerade över de ständiga betalväggarna och sekretessläckorna från traditionella dokumentverktyg online. Att ladda upp känsliga filer till slumpmässiga servrar kändes i sig fel. Vi byggde HandleMyFile för att bevisa att företagsverktyg kan vara gratis, snabba och helt säkra.',
    pageAboutSec2Title: 'Teknikstapel',
    pageAboutSec2Desc: 'Genom att utnyttja kraften i WebAssembly (Wasm) tog vi komplexa C++- och Rust-bibliotek på serversidan och porterade dem så att de körs direkt i din webbläsare. Detta innebär att servern förs till din enhet, vilket helt eliminerar behovet av nätverksuppladdningar.',
    pageAboutSec3Title: 'Vår garanti',
    pageAboutSec3Desc: 'HandleMyFile är byggd för att förbli helt gratis. Vårt uppdrag är att demokratisera dokumentverktyg för alla, överallt.',
    pageAboutSec4Title: 'Gå med i rörelsen',
    pageAboutSec4Desc: 'Vi litar på att vårt samhälle håller detta projekt vid liv. Dela HandleMyFile med dina vänner, familj och kollegor. Tillsammans kan vi bygga en säkrare, snabbare och mer tillgänglig webb.',
    pagePrivacySec1Title: 'Datahanteringsmatris',
    pagePrivacySec1Desc: 'Vi samlar inte in IP-adresser. Vi lagrar inte dina filer. Vi kräver inga e-postregistreringar. Varje enskild bit av din dokumentdata finns alltid kvar uteslutande på din fysiska enhet.',
    pagePrivacySec2Title: 'Hur klientsidan fungerar',
    pagePrivacySec2Desc: 'När du väljer en fil på HandleMyFile läses den in direkt i din webbläsares RAM. WebAssembly-motorn bearbetar filen lokalt och begär en nedladdning direkt från minnet. Filen färdas aldrig över internet.',
    pagePrivacySec3Title: 'Tredjepartsintegrationer',
    pagePrivacySec3Desc: 'Vi är extremt oberoende. Vi bäddar inte in dolda analysspårare, annonsnätverk eller cookies från tredje part som kan äventyra din integritet. Det som händer på HandleMyFile stannar på HandleMyFile.',
    pagePrivacySec4Title: 'Global efterlevnad',
    pagePrivacySec4Desc: 'Eftersom vår arkitektur matematiskt hindrar oss från att komma åt dina filer, överskrider HandleMyFile i sig integritetskraven i GDPR, CCPA och andra globala dataskyddsbestämmelser.',
    pageTosSec1Title: 'Policy för acceptabel användning',
    pageTosSec1Desc: 'Du samtycker till att endast använda HandleMyFile för lagliga ändamål. Du får inte använda våra verktyg för att förfalska, manipulera eller förfalska juridiska dokument, myndighets-ID eller något material för bedrägliga aktiviteter.',
    pageTosSec2Title: 'Immateriella rättigheter',
    pageTosSec2Desc: 'Du behåller 100 % äganderätt och alla immateriella rättigheter till de dokument du behandlar med HandleMyFile. Vi hävdar noll rättigheter, licenser eller äganderätt över ditt innehåll.',
    pageTosSec3Title: 'Serviceändringar',
    pageTosSec3Desc: 'Vi förbehåller oss rätten att när som helst ändra, avbryta eller avbryta någon del av tjänsten utan föregående meddelande. Som en helt klientsida kan vi inte garantera kompatibilitet med alla webbläsarversioner.',
    pageTosSec4Title: 'Ansvarsbegränsning',
    pageTosSec4Desc: 'Under inga omständigheter ska HandleMyFile, dess skapare eller bidragsgivare hållas ansvariga för några direkta, indirekta, oförutsedda skador eller följdskador till följd av användningen eller oförmågan att använda våra verktyg.',
  
    homeGeoDefTitle: 'Vad är HandleMyFile?',
    homeGeoDefDesc: 'HandleMyFile är en 100 % klientsida för dokumentbehandlingsprogram som tillåter användare att redigera, konvertera, slå samman och komprimera PDF- och Office-filer direkt i webbläsaren. Genom att utnyttja WebAssembly (WASM) bearbetar den all data lokalt på din enhet utan att ladda upp något till externa servrar, vilket säkerställer absolut integritet och säkerhet i företagsklass.',
    homeGeoTrustTitle: 'Varför är detta 100 % säkert och privat?',
    homeGeoTrustDesc: 'Till skillnad från traditionella molnbaserade PDF-verktyg som kräver att du laddar upp känsliga dokument till deras servrar, kör HandleMyFile alla algoritmer i din webbläsares säkra sandlåda. Applikationen använder WebAssembly och JavaScript TypedArrays för att manipulera filer lokalt. Denna arkitektur garanterar noll dataläckage.',
    homeGeoTakeawaysTitle: 'Nyckel takeaways',
    homeGeoTakeawaysItem1: 'Bearbeta PDF-filer och Office-filer lokalt i webbläsarens minne.',
    homeGeoTakeawaysItem2: 'Ingen filuppladdning krävs, vilket säkerställer total datasekretess.',
    homeGeoTakeawaysItem3: 'Drivs av WebAssembly för snabba offlinekonverteringar.',
    homeGeoFaqTitle: 'Vanliga frågor',
    homeGeoFaq1Q: 'Hur fungerar HandleMyFile utan en server?',
    homeGeoFaq1A: 'Den använder WebAssembly (WASM) för att köra tunga C++- och Rust-behandlingsbibliotek direkt i din webbläsarmotor.',
    homeGeoFaq2Q: 'Finns det några filstorleksbegränsningar?',
    homeGeoFaq2A: 'Nej. Eftersom bearbetning sker på din lokala enhet är den enda begränsningen din dators tillgängliga RAM-minne.',
