    pagePricingSec3Title: 'Jak je to možné?',
    pagePricingSec3Desc: 'Tradiční nástroje mají drahé účty za server, protože zpracovávají vaše soubory na svém cloudu. Portovali jsme motory C++ a Rust tak, aby běžely ve vašem prohlížeči. Váš počítač odvede těžkou práci, což znamená, že náklady na náš server jsou téměř nulové. Tyto úspory předáme přímo vám.',
    pagePricingSec4Title: 'Udržitelný & Transparentní',
    pagePricingSec4Desc: 'Aby byl HandleMyFile navždy 100% zdarma, spoléháme na nevtíravé reklamy a standardní analýzu webu. Vaše soukromí je však naší nejvyšší prioritou. Nikdy neskenujeme, extrahujeme ani neprodáváme obsah vašich souborů. Co se stane v editoru, zůstane v editoru.',
    pagePricingSec5Title: 'Zdarma pro firemní použití',
    pagePricingSec5Desc: 'Ano, pro vaši společnost můžete použít HandleMyFile. Naše místní architektura zpracování z nás dělá jedinou platformu dostatečně bezpečnou pro přísná firemní prostředí, právní týmy a zdravotnické profesionály.',
    pagePricingSec6Title: 'Podpořte Projekt',
    pagePricingSec6Desc: 'Neúčtujeme předplatné, ale udržet doménu a vývoj při životě nějakou dobu trvá. Pokud vám HandleMyFile zachránil den, zvažte sdílení se svým týmem. Ústní sdělení je naší jedinou marketingovou strategií.',
    shareBtn: 'Sdílejte HandleMyFile',
    footerSecurity: 'Bezpečnost a důvěra',
    pageSecurityHero: 'Matematické soukromí. Nulové nahrávání.',
    pageSecurityHeroSub: 'Většina nástrojů pro práci s dokumenty slibuje, že vaše soubory odstraní po 1 hodině. Slibujeme, že vaše soubory nikdy neuvidíme.',
    pageSecurityBadge: 'Centrum důvěry',
    pageSecuritySec2Title: 'Revoluce WebAssembly',
    pageSecuritySec3Title: 'Vaše dokumenty jsou pro nás slepé',
    pageSecuritySec3Desc: 'I když používáme standardní analýzy ke zlepšení našich webových stránek, naše skripty se nikdy nedotýkají vašich dokumentů. Neextrahujeme metadata, textový obsah ani obrázky. Sandbox pro zpracování dokumentů je zcela samostatný na kartě prohlížeče.',
    pageSecuritySec4Title: 'Soulad ve výchozím nastavení',
    pageSecuritySec4Desc: 'Protože HandleMyFile nemá přístup k vašim souborům, používání našich nástrojů automaticky splňuje nejpřísnější zákony na ochranu dat na celém světě.',
    pageSecuritySec5Title: 'Nevěřte nám. Ověřte to.',
    pageSecuritySec5Desc: 'Nemusíte nás brát za slovo. Naši offline záruku můžete sami prokázat ve 3 jednoduchých krocích:',
    pageSecuritySec6Title: 'Budoucnost je místní',
    pageSecuritySec6Desc: 'Představujeme si web, kde obslužné aplikace respektují váš hardware a vaše soukromí. Vítejte v nové éře počítačů na straně klienta.',
