    compareTr7Col1: 'Behandlingshastighet',
    compareTr7Col2: 'Avhengig av Internett-hastighet',
    compareTr7Col3: 'Øyeblikkelig (lokal CPU)',
    pageCompareExpertTitle: 'Bygget for personvern',
    pageCompareExpertQuote: 'Opplasting av konfidensielle bedriftsdokumenter til sky-API-er kan være en sårbarhet for eksterne team. Behandlingsverktøy på klientsiden som HandleMyFile gir en null-tillit-arkitektur som er egnet for håndtering av sensitive PDF-filer lokalt.',
    pageCompareExpertRole: 'Privacy by Design',
    pageCompareSec3Desc: 'Med eldre skyverktøy, hvis du ønsker å slå sammen tre 50 MB PDF-filer, er du tvunget til å laste opp 150 MB med data. Deretter venter du på at serveren deres skal behandle det. Deretter laster du ned resultatet på 150MB. Det er en 300 MB nettverksflaskehals. HandleMyFile behandler 150 MB umiddelbart på din lokale disk ved hjelp av WebAssembly.',
    pageCompareSec4Title: 'Hold dataene dine private',
    pageCompareSec4Desc: 'Mange online PDF-verktøy forbeholder seg retten til å skanne dine opplastede dokumenter. Vår offline-arkitektur garanterer personvern som standard, gratis. Filene dine forlater aldri enheten.',
    pageCompareSec5Title: 'Unngå filstørrelsesfellen',
    pageCompareSec5Desc: 'Cloud APIer begrenser ofte arbeidsflyten din med grenser på 5 MB. HandleMyFile bruker enhetens RAM, noe som betyr at du kan behandle 1GB+ filer lokalt hvis datamaskinen din kan håndtere det.',
    pageCompareSec6Title: 'Bytt i dag',
    pageCompareSec6Desc: 'Slutt å gå på akkord med hastighet, personvern og kostnader. Bli med tusenvis av fagfolk som allerede har byttet til den raskeste offline dokumentverktøysettet på nettet.',
    pageLangHero: 'Støttede språk',
    pageLangHeroSub: 'HandleMyFile er fullstendig lokalisert på 30 språk.',
    pageLangBadge: 'Global tilgang',
    pageLangSec2Title: 'Innfødt lokalisering',
    pageLangSec3Title: 'Bryt språkbarrierer',
    pageLangSec3Desc: 'Bruk våre offline dokumentverktøy på ditt morsmål. Vi støtter venstre-til-høyre- og høyre-til-venstre-språk med full UI-lokalisering.',
    pageLangSec4Title: 'Ingen skyoversettelse nødvendig',
    pageLangSec4Desc: 'All UI-tekst er samlet direkte i applikasjonen, noe som betyr at du ikke trenger internettilgang for å bytte språk.',
    pageLangSec5Title: 'Sømløs veksling',
    pageLangSec5Desc: 'Bytt språk umiddelbart uten å laste inn programmet på nytt.',
    pageLangSec6Title: 'Klar til å starte?',
    pageLangSec6Desc: 'Velg språket du foretrekker og opplev de raskeste offline dokumentverktøyene på nettet.',
    footerUseCases: 'Případy použití',
    pageUseCasesHero: 'Stvořeno pro každou profesi',
    pageUseCasesHeroSub: 'Od přísných právních prostředí po kreativní agentury, zjistěte, proč profesionálové důvěřují naší architektuře zpracování na straně klienta.',
    pageUseCasesBadge: 'Průmyslová řešení',
    pageUseCasesSec2Title: 'Právní a advokátní kanceláře',
    pageUseCasesSec2Desc: 'Advokáti zpracovávají vysoce důvěrné smlouvy NDA, smlouvy a soudní podání. Nahrávání těchto dokumentů do náhodných cloudových API je hlavní zátěž. S HandleMyFile mohou právní týmy redigovat, slučovat a rozdělovat soubory případů PDF zcela offline, což zajišťuje absolutní důvěrnost klienta.',
    pageUseCasesSec3Title: 'lidské zdroje (HR)',
    pageUseCasesSec3Desc: 'Personální oddělení se denně zabývají PII (Personally Identifiable Information). Skenování ID, zpracování mzdových tabulek a správa nabídkových dopisů vyžaduje přísnou shodu s GDPR/CCPA. HandleMyFile umožňuje personalistům spravovat tyto soubory bez porušení interních zásad bezpečnosti IT.',
    pageUseCasesSec4Title: 'Studenti a vzdělávání',
    pageUseCasesSec4Desc: 'Studenti by neměli platit 20 USD měsíčně jen za sloučení úkolů skupinových projektů nebo komprimaci prezentace tak, aby odpovídala limitu 5 MB pro upload na univerzitním portálu. HandleMyFile poskytuje neomezený přístup k prémiovým nástrojům zdarma, s nulovým omezením velikosti souboru.',
    pageUseCasesSec5Title: 'Realitní kanceláře a makléři',
    pageUseCasesSec5Desc: 'Realitní makléři zpracovávají masivní brožury o nemovitostech plné obrázků ve vysokém rozlišení, které jsou příliš velké na to, aby je bylo možné klientům poslat e-mailem. Potřebují také rychle vodoznakovat plány nemovitostí a podepsat nájemní smlouvy. HandleMyFile okamžitě zpracuje 100 MB+ soubory.',
    pageUseCasesSec6Title: 'Najděte si svůj vlastní případ použití',
    pageUseCasesSec6Desc: 'Bez ohledu na vaše odvětví, pokud pracujete s dokumenty, HandleMyFile je nejbezpečnější a nejrychlejší způsob, jak dokončit práci. Vyzkoušejte naši úplnou sadu 20+ nástrojů ještě dnes.',
    footerCompare: 'Porovnejte',
    pageCompareHero: 'HandleMyFile vs The Rest',
    pageCompareHeroSub: 'Už vás nebaví čekat na nahrání souborů? Frustrovaní limity 5 MB souborů? Zjistěte, proč profesionálové přecházejí na nástroje pro dokumenty na straně klienta.',
    pageCompareBadge: 'Chytrá alternativa',
