    footerPricing: 'Prissætning',
    pagePricingHero: 'Nul abonnementer. Nul grænser.',
    pagePricingHeroSub: 'Dokumentværktøjer i virksomhedskvalitet koster normalt 20 USD om måneden. Vi mener, at privatliv og nytteværdi bør være en grundlæggende menneskeret. HandleMyFile er helt gratis.',
    pagePricingBadge: 'Radikalt fri',
    pagePricingComp: 'Traditionelle skyværktøjer',
    pagePricingSec3Title: 'Hvordan er dette muligt?',
    pagePricingSec3Desc: 'Traditionelle værktøjer har dyre serverregninger, fordi de behandler dine filer på deres sky. Vi porterede C++ og Rust-motorer til at køre i din browser. Din computer gør det tunge løft, hvilket betyder, at vores serveromkostninger er tæt på nul. Vi giver disse besparelser direkte til dig.',
    pagePricingSec4Title: 'Bæredygtig og gennemsigtig',
    pagePricingSec4Desc: 'For at holde HandleMyFile 100 % gratis for evigt, er vi afhængige af ikke-påtrængende annoncer og standard webanalyse. Dit privatliv er dog vores topprioritet. Vi scanner, udtrækker eller sælger aldrig indholdet af dine filer. Hvad der sker i editoren, bliver i editoren.',
    pagePricingSec5Title: 'Gratis til erhvervsbrug',
    pagePricingSec5Desc: 'Ja, du kan bruge HandleMyFile til din virksomhed. Faktisk gør vores lokale behandlingsarkitektur os til den eneste platform, der er sikker nok til strenge virksomhedsmiljøer, juridiske teams og sundhedspersonale.',
    pagePricingSec6Title: 'Støt projektet',
    pagePricingSec6Desc: 'Vi opkræver ikke et abonnement, men det tager tid at holde domænet og udviklingen i live. Hvis HandleMyFile reddede din dag, så overvej at dele den med dit team. Mund til mund er vores eneste marketingstrategi.',
    shareBtn: 'Del HandleMyFile',
    footerSecurity: 'Sikkerhed og tillid',
    pageSecurityHero: 'Matematisk privatliv. Nul uploads.',
    pageSecurityHeroSub: 'De fleste dokumentværktøjer lover, at de sletter dine filer efter 1 time. Vi lover, at vi aldrig ser dine filer i første omgang.',
    pageSecurityBadge: 'Tillidscenter',
    pageSecuritySec2Title: 'WebAssembly-revolutionen',
    pageSecuritySec3Title: 'Dine dokumenter er blinde for os',
    pageSecuritySec3Desc: 'Selvom vi bruger standardanalyse til at forbedre vores hjemmesideoplevelse, rører vores scripts aldrig dine dokumenter. Vi udtrækker ikke metadata, tekstindhold eller billeder. Sandkassen til dokumentbehandling er fuldstændig selvstændig i din browserfane.',
    pageSecuritySec4Title: 'Overholdelse som standard',
    pageSecuritySec4Desc: 'Fordi HandleMyFile ikke kan få adgang til dine filer, overholder brugen af ​​vores værktøjer automatisk de strengeste databeskyttelseslove i hele verden.',
    pageSecuritySec5Title: 'Stol ikke på os. Bekræft det.',
    pageSecuritySec5Desc: 'Du behøver ikke tage vores ord for det. Du kan selv bevise vores offline-garanti i 3 enkle trin:',
    pageSecuritySec6Title: 'Fremtiden er lokal',
    pageSecuritySec6Desc: 'Vi forestiller os et web, hvor hjælpeapps respekterer din hardware og dit privatliv. Velkommen til den nye æra af klient-side computing.',
