    compareTr7Col1: 'Viteza de procesare',
    compareTr7Col2: 'Depinde de viteza Internetului',
    compareTr7Col3: 'Instantaneu (procesor local)',
    pageCompareExpertTitle: 'Construit pentru confidențialitate',
    pageCompareExpertQuote: 'Încărcarea documentelor corporative confidențiale în API-urile cloud poate fi o vulnerabilitate pentru echipele aflate la distanță. Instrumentele de procesare la nivelul clientului, cum ar fi HandleMyFile, oferă o arhitectură de încredere zero, potrivită pentru gestionarea locală a PDF-urilor sensibile.',
    pageCompareExpertRole: 'Confidențialitate prin design',
    pageCompareSec3Desc: 'Cu instrumentele cloud vechi, dacă doriți să îmbinați trei PDF-uri de 50 MB, sunteți forțat să încărcați 150 MB de date. Apoi așteptați ca serverul lor să o proceseze. Apoi descărcați rezultatul de 150 MB. Acesta este un blocaj de rețea de 300 MB. HandleMyFile procesează instantaneu cei 150 MB de pe discul local folosind WebAssembly.',
    pageCompareSec4Title: 'Păstrați datele dvs. private',
    pageCompareSec4Desc: 'Multe instrumente PDF online își rezervă dreptul de a scana documentele încărcate. Arhitectura noastră offline garantează confidențialitatea în mod implicit, gratuit. Fișierele dvs. nu părăsesc niciodată dispozitivul dvs.',
    pageCompareSec5Title: 'Scăpați de capcana pentru dimensiunea fișierului',
    pageCompareSec5Desc: 'API-urile cloud vă limitează adesea fluxul de lucru cu limite de 5 MB. HandleMyFile folosește memoria RAM a dispozitivului dvs., ceea ce înseamnă că puteți procesa fișiere de peste 1 GB la nivel local, dacă computerul îl poate gestiona.',
    pageCompareSec6Title: 'Schimbați astăzi',
    pageCompareSec6Desc: 'Nu mai faceți compromisuri în ceea ce privește viteza, confidențialitatea și costul. Alăturați-vă miilor de profesioniști care au trecut deja la cel mai rapid set de instrumente pentru documente offline de pe web.',
    pageLangHero: 'Limbi acceptate',
    pageLangHeroSub: 'HandleMyFile este complet localizat în 30 de limbi.',
    pageLangBadge: 'Acces global',
    pageLangSec2Title: 'Localizare nativă',
    pageLangSec3Title: 'Rupe barierele lingvistice',
    pageLangSec3Desc: 'Utilizați instrumentele noastre de documente offline în limba dvs. maternă. Acceptăm limbi de la stânga la dreapta și de la dreapta la stânga cu localizare completă a interfeței de utilizare.',
    pageLangSec4Title: 'Nu este necesară traducerea în cloud',
    pageLangSec4Desc: 'Tot textul UI este inclus direct în aplicație, ceea ce înseamnă că nu aveți nevoie de acces la internet pentru a schimba limbile.',
    pageLangSec5Title: 'Comutare fără întreruperi',
    pageLangSec5Desc: 'Schimbați limbile instantaneu fără a reîncărca aplicația.',
    pageLangSec6Title: 'Sunteți gata să începeți?',
    pageLangSec6Desc: 'Selectați limba preferată și experimentați cele mai rapide instrumente de documente offline de pe web.',
    footerUseCases: 'Brug Cases',
    pageUseCasesHero: 'Bygget til enhver profession',
    pageUseCasesHeroSub: 'Fra strenge juridiske miljøer til kreative bureauer, opdag, hvorfor fagfolk stoler på vores behandlingsarkitektur på klientsiden.',
    pageUseCasesBadge: 'Industriløsninger',
    pageUseCasesSec2Title: 'Advokat- og advokatfirmaer',
    pageUseCasesSec2Desc: 'Advokater håndterer yderst fortrolige NDA\'er, kontrakter og retssager. Upload af disse dokumenter til tilfældige cloud-API\'er er et stort ansvar. Med HandleMyFile kan juridiske teams redigere, flette og opdele PDF-sagsfiler helt offline, hvilket sikrer absolut klientfortrolighed.',
    pageUseCasesSec3Title: 'Menneskelige ressourcer (HR)',
    pageUseCasesSec3Desc: 'HR-afdelinger beskæftiger sig med PII (Personal Identificable Information) på daglig basis. Scanning af ID\'er, håndtering af lønregneark og håndtering af tilbudsbreve kræver streng overholdelse af GDPR/CCPA. HandleMyFile lader HR-professionelle administrere disse filer uden at overtræde interne it-sikkerhedspolitikker.',
    pageUseCasesSec4Title: 'Studerende & Uddannelse',
    pageUseCasesSec4Desc: 'Studerende skal ikke betale 20 USD/måned bare for at flette deres gruppeprojektopgaver eller komprimere en præsentation, så den passer til universitetsportalens uploadgrænse på 5 MB. HandleMyFile giver ubegrænset adgang til premium-værktøjer gratis, med nul filstørrelsesgrænser.',
    pageUseCasesSec5Title: 'Ejendomsmæglere og mæglere',
    pageUseCasesSec5Desc: 'Ejendomsmæglere håndterer massive ejendomsbrochurer spækket med billeder i høj opløsning, der er for store til at e-maile til kunderne. De skal også hurtigt vandmærke ejendomsplaner og underskrive lejeaftaler. HandleMyFile håndterer 100MB+ filer med det samme.',
    pageUseCasesSec6Title: 'Find din egen brugssag',
    pageUseCasesSec6Desc: 'Uanset din branche, hvis du arbejder med dokumenter, er HandleMyFile den sikreste og hurtigste måde at få arbejdet gjort. Prøv vores fulde pakke med mere end 20 værktøjer i dag.',
    footerCompare: 'Sammenligne',
    pageCompareHero: 'HandleMyFile vs The Rest',
    pageCompareHeroSub: 'Træt af at vente på, at filer uploades? Frustreret over 5MB filgrænser? Opdag, hvorfor fagfolk skifter til dokumentværktøjer på klientsiden.',
    pageCompareBadge: 'Det smarte alternativ',
    pageCompareSec2Title: 'Funktionssammenligning',
    pageCompareSec3Title: 'Stop med at vente på fremskridtsbjælker',
    brandDescription: 'Alt-i-en Zero-Upload WebAssembly-dokumentplatform på klientsiden',
