    footerPricing: 'Τιμολόγηση',
    pagePricingHero: 'Μηδενικές Συνδρομές. Μηδενικά Όρια.',
    pagePricingHeroSub: 'Τα εργαλεία εγγράφων εταιρικής ποιότητας συνήθως κοστίζουν 20 $/μήνα. Πιστεύουμε ότι το απόρρητο και η χρησιμότητα πρέπει να είναι θεμελιώδες ανθρώπινο δικαίωμα. Το HandleMyFile είναι εντελώς δωρεάν.',
    pagePricingBadge: 'Ριζικά Δωρεάν',
    pagePricingComp: 'Παραδοσιακά Εργαλεία Cloud',
    pagePricingSec3Title: 'Πώς είναι δυνατόν αυτό;',
    pagePricingSec3Desc: 'Τα παραδοσιακά εργαλεία έχουν ακριβούς λογαριασμούς διακομιστή επειδή επεξεργάζονται τα αρχεία σας στο σύννεφο τους. Μεταφέραμε τις μηχανές C++ και Rust για να εκτελούνται μέσα στο πρόγραμμα περιήγησής σας. Ο υπολογιστής σας κάνει τη βαριά ανύψωση, που σημαίνει ότι το κόστος του διακομιστή μας είναι σχεδόν μηδενικό. Περνάμε αυτές τις οικονομίες απευθείας σε εσάς.',
    pagePricingSec4Title: 'Βιώσιμο & Διαφανές',
    pagePricingSec4Desc: 'Για να διατηρήσουμε το HandleMyFile 100% δωρεάν για πάντα, βασιζόμαστε σε μη παρεμβατικές διαφημίσεις και τυπικά αναλυτικά στοιχεία ιστού. Ωστόσο, το απόρρητό σας είναι η πρώτη μας προτεραιότητα. Ποτέ δεν σαρώνουμε, εξάγουμε ή πουλάμε τα περιεχόμενα των αρχείων σας. Ό,τι συμβαίνει στον επεξεργαστή, μένει στον επεξεργαστή.',
    pagePricingSec5Title: 'Δωρεάν για επαγγελματική χρήση',
    pagePricingSec5Desc: 'Ναι, μπορείτε να χρησιμοποιήσετε το HandleMyFile για την εταιρεία σας. Στην πραγματικότητα, η τοπική αρχιτεκτονική επεξεργασίας μας καθιστά τη μόνη πλατφόρμα αρκετά ασφαλή για αυστηρά εταιρικά περιβάλλοντα, νομικές ομάδες και επαγγελματίες υγείας.',
    pagePricingSec6Title: 'Υποστήριξη του Έργου',
    pagePricingSec6Desc: 'Δεν χρεώνουμε συνδρομή, αλλά η διατήρηση του τομέα και της ανάπτυξης ζωντανές απαιτεί χρόνο. Εάν το HandleMyFile σας έσωσε την ημέρα, σκεφτείτε να το μοιραστείτε με την ομάδα σας. Από στόμα σε στόμα είναι η μόνη μας στρατηγική μάρκετινγκ.',
    shareBtn: 'Κοινή χρήση HandleMyFile',
    footerSecurity: 'Ασφάλεια & Εμπιστοσύνη',
    pageSecurityHero: 'Μαθηματικό απόρρητο. Μηδενικές μεταφορτώσεις.',
    pageSecurityHeroSub: 'Τα περισσότερα εργαλεία εγγράφων υπόσχονται ότι θα διαγράψουν τα αρχεία σας μετά από 1 ώρα. Υποσχόμαστε ότι δεν θα δούμε ποτέ τα αρχεία σας από την αρχή.',
    pageSecurityBadge: 'Κέντρο εμπιστοσύνης',
    pageSecuritySec2Title: 'Η Επανάσταση WebAssembly',
    pageSecuritySec3Title: 'Τα έγγραφά σας είναι τυφλά για εμάς',
    pageSecuritySec3Desc: 'Ενώ χρησιμοποιούμε τυπικά αναλυτικά στοιχεία για να βελτιώσουμε την εμπειρία του ιστότοπού μας, τα σενάρια μας δεν αγγίζουν ποτέ τα έγγραφά σας. Δεν εξάγουμε μεταδεδομένα, περιεχόμενο κειμένου ή εικόνες. Το περιβάλλον δοκιμών επεξεργασίας εγγράφων είναι εξ ολοκλήρου αυτόνομο στην καρτέλα του προγράμματος περιήγησής σας.',
    pageSecuritySec4Title: 'Συμμόρφωση από προεπιλογή',
    pageSecuritySec4Desc: 'Επειδή το HandleMyFile δεν μπορεί να έχει πρόσβαση στα αρχεία σας, η χρήση των εργαλείων μας συμμορφώνεται αυτόματα με τους αυστηρότερους νόμους προστασίας δεδομένων παγκοσμίως.',
    pageSecuritySec5Title: 'Μην μας εμπιστεύεστε. Επαληθεύστε το.',
    pageSecuritySec5Desc: 'Δεν χρειάζεται να δεχθείτε τα λόγια μας. Μπορείτε να αποδείξετε την εγγύησή μας εκτός σύνδεσης με 3 απλά βήματα:',
    pageSecuritySec6Title: 'Το Μέλλον είναι Τοπικό',
    pageSecuritySec6Desc: 'Οραματιζόμαστε έναν ιστό όπου οι εφαρμογές βοηθητικού προγράμματος σέβονται το υλικό και το απόρρητό σας. Καλώς ήρθατε στη νέα εποχή των υπολογιστών από την πλευρά του πελάτη.',
