    pagePricingSec3Title: 'Miten tämä on mahdollista?',
    pagePricingSec3Desc: 'Perinteisillä työkaluilla on kalliita palvelinlaskuja, koska ne käsittelevät tiedostosi pilvessään. Siirsimme C++- ja Rust-moottorit toimimaan selaimesi sisällä. Tietokoneesi hoitaa raskaat työt, mikä tarkoittaa, että palvelinkustannukset ovat lähellä nollaa. Välitämme nämä säästöt suoraan sinulle.',
    pagePricingSec4Title: 'Kestävä & läpinäkyvä',
    pagePricingSec4Desc: 'Jotta HandleMyFile pysyy 100 % ilmaiseksi ikuisesti, luotamme ei-tunkeileviin mainoksiin ja tavalliseen verkkoanalytiikkaan. Yksityisyytesi on kuitenkin meille tärkein prioriteetti. Emme koskaan skannaa, pura tai myy tiedostojesi sisältöä. Se, mitä tapahtuu editorissa, pysyy editorissa.',
    pagePricingSec5Title: 'Ilmainen yrityskäyttöön',
    pagePricingSec5Desc: 'Kyllä, voit käyttää HandleMyFileä yrityksellesi. Itse asiassa paikallinen käsittelyarkkitehtuurimme tekee meistä ainoan tarpeeksi turvallisen alustan tiukoille yritysympäristöille, lakitiimeille ja terveydenhuollon ammattilaisille.',
    pagePricingSec6Title: 'Tue projektia',
    pagePricingSec6Desc: 'Emme veloita tilausta, mutta verkkotunnuksen ja kehityksen hengissä pitäminen vie aikaa. Jos HandleMyFile pelasti päiväsi, harkitse sen jakamista tiimillesi. Word of mouth on ainoa markkinointistrategiamme.',
    shareBtn: 'Jaa HandleMyFile',
    footerSecurity: 'Turvallisuus ja luottamus',
    pageSecurityHero: 'Matemaattinen yksityisyys. Nolla latausta.',
    pageSecurityHeroSub: 'Useimmat asiakirjatyökalut lupaavat poistaa tiedostosi tunnin kuluttua. Lupaamme, että emme koskaan näe tiedostojasi.',
    pageSecurityBadge: 'Luottamuskeskus',
    pageSecuritySec2Title: 'WebAssembly Revolution',
    pageSecuritySec3Title: 'Asiakirjasi ovat meille sokeita',
    pageSecuritySec3Desc: 'Vaikka käytämme tavallista analytiikkaa parantaaksemme verkkosivustomme käyttökokemusta, skriptimme eivät koskaan kosketa asiakirjojasi. Emme poimi metatietoja, tekstisisältöä tai kuvia. Asiakirjojen käsittelyn hiekkalaatikko on täysin itsenäinen selaimen välilehdessä.',
    pageSecuritySec4Title: 'Yhteensopivuus oletuksena',
    pageSecuritySec4Desc: 'Koska HandleMyFile ei pääse käsiksi tiedostoihisi, työkalujemme käyttö noudattaa automaattisesti maailmanlaajuisesti tiukimpia tietosuojalakeja.',
    pageSecuritySec5Title: 'Älä luota meihin. Vahvista se.',
    pageSecuritySec5Desc: 'Sinun ei tarvitse uskoa sanaamme. Voit todistaa offline-takuumme itsellesi kolmella yksinkertaisella vaiheella:',
    pageSecuritySec6Title: 'Tulevaisuus on paikallinen',
    pageSecuritySec6Desc: 'Kuvittelemme verkkoa, jossa apuohjelmat kunnioittavat laitteistoasi ja yksityisyyttäsi. Tervetuloa asiakaspuolen tietojenkäsittelyn uuteen aikakauteen.',
