    compareTr7Col3: 'Segera (CPU Tempatan)',
    pageCompareExpertTitle: 'Dibina untuk Privasi',
    pageCompareExpertQuote: 'Memuat naik dokumen korporat sulit ke API awan boleh menjadi kelemahan untuk pasukan jauh. Alat pemprosesan sebelah pelanggan seperti HandleMyFile menyediakan seni bina amanah sifar yang sesuai untuk mengendalikan PDF sensitif secara tempatan.',
    pageCompareExpertRole: 'Privasi oleh Reka Bentuk',
    pageCompareSec3Desc: 'Dengan alatan awan lama, jika anda ingin menggabungkan tiga PDF 50MB, anda terpaksa memuat naik 150MB data. Kemudian anda menunggu pelayan mereka memprosesnya. Kemudian anda memuat turun hasil 150MB. Itu adalah kesesakan rangkaian 300MB. HandleMyFile memproses 150MB serta-merta pada cakera tempatan anda menggunakan WebAssembly.',
    pageCompareSec4Title: 'Simpan Data Anda Peribadi',
    pageCompareSec4Desc: 'Banyak alat PDF dalam talian berhak untuk mengimbas dokumen yang anda muat naik. Seni bina luar talian kami menjamin privasi secara lalai, secara percuma. Fail anda tidak pernah meninggalkan peranti anda.',
    pageCompareSec5Title: 'Melarikan diri daripada Perangkap Saiz Fail',
    pageCompareSec5Desc: 'Cloud API selalunya mengehadkan aliran kerja anda dengan had 5MB. HandleMyFile menggunakan RAM peranti anda, bermakna anda boleh memproses 1GB+ fail secara setempat jika komputer anda boleh mengendalikannya.',
    pageCompareSec6Title: 'Tukar Hari Ini',
    pageCompareSec6Desc: 'Berhenti berkompromi pada kelajuan, privasi dan kos. Sertai beribu-ribu profesional yang telah bertukar kepada kit alat dokumen luar talian terpantas di web.',
    pageLangHero: 'Bahasa yang Disokong',
