    pageLangSec3Title: 'Memecahkan Halangan Bahasa',
    pageLangSec3Desc: 'Gunakan alat dokumen luar talian kami dalam bahasa ibunda anda. Kami menyokong bahasa kiri ke kanan dan kanan ke kiri dengan penyetempatan UI penuh.',
    pageLangSec4Title: 'Tiada Terjemahan Awan Diperlukan',
    pageLangSec4Desc: 'Semua teks UI digabungkan terus ke dalam aplikasi, bermakna anda tidak memerlukan akses internet untuk menukar bahasa.',
    pageLangSec5Title: 'Penukaran Lancar',
    pageLangSec5Desc: 'Tukar bahasa serta-merta tanpa memuatkan semula aplikasi.',
    pageLangSec6Title: 'Bersedia untuk Bermula?',
    pageLangSec6Desc: 'Pilih bahasa pilihan anda dan alami alat dokumen luar talian terpantas di web.',
    footerUseCases: 'Käyttötapaukset',
    pageUseCasesHero: 'Rakennettu jokaiselle ammatille',
    pageUseCasesHeroSub: 'Selvitä, miksi ammattilaiset luottavat asiakaspuolen prosessointiarkkitehtuuriimme tiukoista oikeudellisista ympäristöistä luoviin toimistoihin.',
    pageUseCasesBadge: 'Teollisuuden ratkaisut',
    pageUseCasesSec2Title: 'Lakiasiaintoimistot',
    pageUseCasesSec2Desc: 'Asianajajat käsittelevät erittäin luottamuksellisia NDA-sopimuksia, sopimuksia ja oikeuskäsittelyjä. Näiden asiakirjojen lataaminen satunnaisiin pilvisovellusliittymiin on suuri vastuu. HandleMyFilen avulla lakitiimit voivat muokata, yhdistää ja jakaa PDF-tapaustiedostoja täysin offline-tilassa, mikä varmistaa asiakkaiden ehdottoman luottamuksellisuuden.',
    pageUseCasesSec3Title: 'Henkilöstöresurssit (HR)',
    pageUseCasesSec3Desc: 'HR-osastot käsittelevät PII:tä (Personally Identifiable Information) päivittäin. Tunnusten skannaus, palkkalaskentataulukkojen käsittely ja tarjouskirjeiden hallinta edellyttää tiukkaa GDPR/CCPA-vaatimustenmukaisuutta. HandleMyFile antaa HR-ammattilaisten hallita näitä tiedostoja rikkomatta sisäisiä IT-suojauskäytäntöjä.',
    pageUseCasesSec4Title: 'Opiskelijat ja koulutus',
    pageUseCasesSec4Desc: 'Opiskelijoiden ei pitäisi joutua maksamaan 20 dollaria kuukaudessa vain yhdistääkseen ryhmäprojektitehtävänsä tai pakatakseen esityksen yliopistoportaalin 5 Mt:n latausrajaan. HandleMyFile tarjoaa rajoittamattoman pääsyn premium-työkaluihin ilmaiseksi, ilman tiedostokokorajoituksia.',
    pageUseCasesSec5Title: 'Kiinteistöt ja välittäjät',
    pageUseCasesSec5Desc: 'Kiinteistönvälittäjät käsittelevät valtavia kiinteistöesitteitä, jotka on täynnä korkearesoluutioisia kuvia, jotka ovat liian suuria lähettää asiakkaille sähköpostitse. Heidän on myös tehtävä nopeasti vesileima kiinteistösuunnitelmat ja allekirjoitettava vuokrasopimukset. HandleMyFile käsittelee yli 100 Mt tiedostoja välittömästi.',
    pageUseCasesSec6Title: 'Löydä oma käyttötapasi',
    pageUseCasesSec6Desc: 'Toimialastasi riippumatta, jos työskentelet asiakirjojen parissa, HandleMyFile on turvallisin ja nopein tapa tehdä työsi. Kokeile täyttä 20+ työkaluvalikoimaamme jo tänään.',
    footerCompare: 'Vertaa',
    pageCompareHero: 'HandleMyFile vs The Rest',
    pageCompareHeroSub: 'Oletko kyllästynyt odottamaan tiedostojen lataamista? Oletko turhautunut 5 Mt:n tiedostorajoituksiin? Ota selvää, miksi ammattilaiset vaihtavat asiakaspuolen dokumenttityökaluihin.',
