    zeroUploadGuarantee: 'Miksi tämä on 100 % suojattu ja yksityinen?',
    zeroUploadDetails: 'Toisin kuin perinteiset pilvimuuntimet, jotka lataavat yksityisiä asiakirjojasi etäpalvelimille, alustamme suorittaa C/C++ WebAssembly -moottorit suoraan selaimesi RAM-muistissa. Luottamukselliset asiakirjasi eivät koskaan kulje Internetin läpi.',
    faqTitle: 'Usein kysytyt kysymykset',
    backToHome: '← Takaisin kaikkiin työkaluihin',
    languageSelect: 'Valitse Kieli',
    footerRights: 'Kaikki oikeudet pidätetään. Powered by WebAssembly Client-Side Architecture.',
    privacyTitle: 'Absoluuttinen nollalatausturva',
    privacyText: 'Yritysten lakisääteisten tietosuojavaatimusten (GDPR/HIPAA) mukainen. Ei palvelimen tallennusta, ei tietojen kirjaamista, ei keinotekoisia rajoituksia.',
    pageAboutSec1Title: 'Alkuperätarina',
    pageAboutSec1Desc: 'Olimme turhautuneet perinteisten online-dokumenttityökalujen jatkuviin maksumuureihin ja tietosuojavuotojin. Arkaluonteisten tiedostojen lataaminen satunnaisille palvelimille tuntui luonnostaan ​​väärin. Rakensimme HandleMyFilen todistaaksemme, että yritystason työkalut voivat olla ilmaisia, nopeita ja täysin turvallisia.',
    pageAboutSec2Title: 'Teknologiapino',
    pageAboutSec2Desc: 'Hyödyntämällä WebAssemblyn (Wasm) tehoa otimme monimutkaiset palvelinpuolen C++- ja Rust-kirjastot ja siirsimme ne toimimaan suoraan verkkoselaimesi sisällä. Tämä tarkoittaa, että palvelin tuodaan laitteellesi, mikä eliminoi kokonaan verkkolatausten tarpeen.',
    pageAboutSec3Title: 'Takuumme',
    pageAboutSec3Desc: 'HandleMyFile on rakennettu pysymään täysin vapaana. Missiomme on demokratisoida asiakirja-apuohjelmat kaikille ja kaikkialla.',
    pageAboutSec4Title: 'Liity Liikkeeseen',
    pageAboutSec4Desc: 'Luotamme yhteisöömme pitämään tämän projektin hengissä. Jaa HandleMyFile ystävien, perheen ja työtovereiden kanssa. Yhdessä voimme rakentaa turvallisemman, nopeamman ja helppokäyttöisemmän verkon.',
    pagePrivacySec1Title: 'Tiedonkäsittelymatriisi',
    pagePrivacySec1Desc: 'Emme kerää IP-osoitteita. Emme tallenna tiedostojasi. Emme vaadi sähköpostirekisteröintiä. Jokainen bitti dokumenttidataa säilyy yksinomaan fyysisellä laitteellasi koko ajan.',
    pagePrivacySec2Title: 'Miten asiakaspuoli toimii',
    pagePrivacySec2Desc: 'Kun valitset tiedoston HandleMyFilessä, se ladataan suoraan selaimesi RAM-muistiin. WebAssembly-moottori käsittelee tiedoston paikallisesti ja kehottaa lataamaan sen suoraan muistista. Tiedosto ei koskaan kulje Internetissä.',
    pagePrivacySec3Title: 'Kolmannen osapuolen integraatiot',
    pagePrivacySec3Desc: 'Olemme erittäin itsenäisiä. Emme upota piilotettuja analytiikkaseurantalaitteita, mainosverkostoja tai kolmannen osapuolen evästeitä, jotka voivat vaarantaa yksityisyytesi. Se, mitä tapahtuu HandleMyFilessä, pysyy HandleMyFilessä.',
    pagePrivacySec4Title: 'Globaali vaatimustenmukaisuus',
    pagePrivacySec4Desc: 'Koska arkkitehtuurimme estää meitä pääsemästä tiedostoihisi matemaattisesti, HandleMyFile ylittää luonnostaan ​​GDPR:n, CCPA:n ja muiden maailmanlaajuisten tietosuojamääräysten tietosuojavaatimukset.',
    pageTosSec1Title: 'Hyväksytty käyttökäytäntö',
    pageTosSec1Desc: 'Suostut käyttämään HandleMyFileä vain laillisiin tarkoituksiin. Et saa käyttää työkalujamme väärentämään, manipuloimaan tai väärentämään laillisia asiakirjoja, viranomaisia ​​henkilöllisyystodistuksia tai mitään materiaalia vilpilliseen toimintaan.',
    pageTosSec2Title: 'Immateriaaliomaisuus',
    pageTosSec2Desc: 'Säilytät HandleMyFilen avulla käsittelemiesi asiakirjojen 100 % omistusoikeuden ja kaikki immateriaalioikeudet. Vaadimme, että sisältöösi ei ole oikeuksia, lisenssejä tai omistajuutta.',
    pageTosSec3Title: 'Palvelun muutokset',
    pageTosSec3Desc: 'Varaamme oikeuden muuttaa, keskeyttää tai lopettaa mitä tahansa Palvelun osaa milloin tahansa ilman ennakkoilmoitusta. Täysin asiakaspuolen alustana emme voi taata yhteensopivuutta kaikkien selainversioiden kanssa.',
    pageTosSec4Title: 'Vastuun rajoitus',
    pageTosSec4Desc: 'HandleMyFile, sen tekijät tai avustajat eivät ole missään olosuhteissa vastuussa suorista, epäsuorista, satunnaisista tai välillisistä vahingoista, jotka johtuvat työkalujemme käytöstä tai kyvyttömyydestä käyttää.',
  
    homeGeoDefTitle: 'Mikä HandleMyFile on?',
    homeGeoDefDesc: 'HandleMyFile on 100 % asiakaspuolen asiakirjojen käsittelysovellus, jonka avulla käyttäjät voivat muokata, muuntaa, yhdistää ja pakata PDF- ja Office-tiedostoja suoraan selaimessa. Hyödyntämällä WebAssemblya (WASM), se käsittelee kaikki tiedot paikallisesti laitteessasi lataamatta mitään ulkoisille palvelimille, mikä varmistaa ehdottoman yksityisyyden ja yritystason turvallisuuden.',
    homeGeoTrustTitle: 'Miksi tämä on 100 % suojattu ja yksityinen?',
    homeGeoTrustDesc: 'Toisin kuin perinteiset pilvipohjaiset PDF-työkalut, jotka edellyttävät arkaluontoisten asiakirjojen lähettämistä palvelimilleen, HandleMyFile suorittaa kaikki algoritmit selaimesi suojatussa hiekkalaatikossa. Sovellus käyttää WebAssembly- ja JavaScript TypedArrays -työkaluja tiedostojen käsittelemiseen paikallisesti. Tämä arkkitehtuuri takaa nollan tietovuotoja.',
    homeGeoTakeawaysTitle: 'Avaimet takeawayt',
    homeGeoTakeawaysItem1: 'Käsittele PDF- ja Office-tiedostoja paikallisesti selaimesi muistissa.',
    homeGeoTakeawaysItem2: 'Ei vaadi tiedostoja, mikä takaa täydellisen tietosuojan.',
    homeGeoTakeawaysItem3: 'Powered by WebAssembly nopeita offline-muunnoksia varten.',
    homeGeoFaqTitle: 'Usein kysytyt kysymykset',
    homeGeoFaq1Q: 'Kuinka HandleMyFile toimii ilman palvelinta?',
    homeGeoFaq1A: 'Se käyttää WebAssemblya (WASM) raskaiden C++- ja Rust-käsittelykirjastojen ajamiseen suoraan verkkoselainmoottorisi sisällä.',
    homeGeoFaq2Q: 'Onko tiedostokokorajoituksia?',
    homeGeoFaq2A: 'Ei. Koska käsittely tapahtuu paikallisella laitteellasi, ainoa raja on tietokoneesi käytettävissä oleva RAM-muisti.',
    homeGeoFaq3Q: 'Onko tämä turvallista luottamuksellisille yritysasiakirjoille?',
    homeGeoFaq3A: 'Kyllä, se on turvallisin käytettävissä oleva menetelmä. Tiedostot eivät koskaan poistu laitteestasi, eikä niitä koskaan välitetä Internetin kautta.',
    homeGeoFaq4Q: 'Toimiiko se täysin offline-tilassa?',
