    footerPricing: 'תמחור',
    pagePricingHero: 'אפס מנויים. אפס גבולות.',
    pagePricingHeroSub: 'כלי מסמכים ברמה ארגונית עולים בדרך כלל $20 לחודש. אנו מאמינים שפרטיות ושימושיות צריכות להיות זכות אדם בסיסית. HandleMyFile הוא חינמי לחלוטין.',
    pagePricingBadge: 'חופשי באופן קיצוני',
    pagePricingComp: 'כלי ענן מסורתיים',
    pagePricingSec3Title: 'איך זה אפשרי?',
    pagePricingSec3Desc: 'לכלים מסורתיים יש חשבונות שרת יקרים מכיוון שהם מעבדים את הקבצים שלך בענן שלהם. העברנו מנועי C++ ו-Rust כדי לפעול בתוך הדפדפן שלך. המחשב שלך עושה את המשימות הכבדות, כלומר עלויות השרת שלנו כמעט אפס. אנו מעבירים את החיסכון ישירות אליך.',
    pagePricingSec4Title: 'בר קיימא ושקוף',
    pagePricingSec4Desc: 'כדי לשמור על HandleMyFile 100% בחינם לנצח, אנו מסתמכים על פרסומות לא פולשניות וניתוח אינטרנט סטנדרטי. עם זאת, הפרטיות שלך היא בראש סדר העדיפויות שלנו. אנחנו לעולם לא סורקים, מחלצים או מוכרים את תוכן הקבצים שלך. מה שקורה בעורך, נשאר בעורך.',
    pagePricingSec5Title: 'חינם לשימוש עסקי',
    pagePricingSec5Desc: 'כן, אתה יכול להשתמש ב- HandleMyFile עבור החברה שלך. למעשה, ארכיטקטורת העיבוד המקומית שלנו הופכת אותנו לפלטפורמה היחידה הבטוחה מספיק עבור סביבות ארגוניות קפדניות, צוותים משפטיים ואנשי מקצוע בתחום הבריאות.',
    pagePricingSec6Title: 'תמכו בפרויקט',
    pagePricingSec6Desc: 'אנחנו לא גובים מנוי, אבל לשמור על הדומיין והפיתוח בחיים לוקח זמן. אם HandleMyFile הציל את היום שלך, שקול לשתף אותו עם הצוות שלך. מפה לאוזן היא האסטרטגיה השיווקית היחידה שלנו.',
    shareBtn: 'שתף את HandleMyFile',
    footerSecurity: 'אבטחה ואמון',
    pageSecurityHero: 'פרטיות מתמטית. אפס העלאות.',
    pageSecurityHeroSub: 'רוב כלי המסמכים מבטיחים שהם מוחקים את הקבצים שלך לאחר שעה. אנו מבטיחים שלעולם לא נראה את הקבצים שלך מלכתחילה.',
    pageSecurityBadge: 'מרכז אמון',
    pageSecuritySec2Title: 'מהפכת WebAssembly',
