    footerPricing: 'Prissetting',
    pagePricingHero: 'Null abonnementer. Null grenser.',
    pagePricingHeroSub: 'Enterprise-grade dokumentverktøy koster vanligvis $20/måned. Vi mener personvern og nytteverdi bør være en grunnleggende menneskerettighet. HandleMyFile er helt gratis.',
    pagePricingBadge: 'Radikalt gratis',
    pagePricingComp: 'Tradisjonelle skyverktøy',
    pagePricingSec3Title: 'Hvordan er dette mulig?',
    pagePricingSec3Desc: 'Tradisjonelle verktøy har dyre serverregninger fordi de behandler filene dine på skyen deres. Vi porterte C++ og Rust-motorer for å kjøre i nettleseren din. Datamaskinen din gjør det tunge løftet, noe som betyr at serverkostnadene våre er nær null. Vi overfører disse besparelsene direkte til deg.',
    pagePricingSec4Title: 'Bærekraftig og gjennomsiktig',
    pagePricingSec4Desc: 'For å holde HandleMyFile 100 % gratis for alltid, er vi avhengige av ikke-påtrengende annonser og standard nettanalyse. Personvernet ditt er imidlertid vår høyeste prioritet. Vi skanner, trekker ut eller selger aldri innholdet i filene dine. Det som skjer i redaktøren, blir i redaktøren.',
    pagePricingSec5Title: 'Gratis for forretningsbruk',
    pagePricingSec5Desc: 'Ja, du kan bruke HandleMyFile for din bedrift. Faktisk gjør vår lokale prosesseringsarkitektur oss til den eneste plattformen som er trygg nok for strenge bedriftsmiljøer, juridiske team og helsepersonell.',
    pagePricingSec6Title: 'Støtt prosjektet',
    pagePricingSec6Desc: 'Vi tar ikke abonnement, men å holde domenet og utviklingen i live tar tid. Hvis HandleMyFile reddet dagen din, bør du vurdere å dele den med teamet ditt. Ord til munn er vår eneste markedsføringsstrategi.',
    shareBtn: 'Del HandleMyFile',
    footerSecurity: 'Sikkerhet og tillit',
    pageSecurityHero: 'Matematisk personvern. Null opplastinger.',
    pageSecurityHeroSub: 'De fleste dokumentverktøy lover at de sletter filene dine etter 1 time. Vi lover at vi aldri ser filene dine med det første.',
    pageSecurityBadge: 'Tillitssenter',
    pageSecuritySec2Title: 'WebAssembly-revolusjonen',
    pageSecuritySec3Title: 'Dokumentene dine er blinde for oss',
    pageSecuritySec3Desc: 'Selv om vi bruker standardanalyse for å forbedre nettsideopplevelsen vår, berører skriptene våre aldri dokumentene dine. Vi trekker ikke ut metadata, tekstinnhold eller bilder. Sandkassen for dokumentbehandling er helt selvstendig i nettleserfanen.',
    pageSecuritySec4Title: 'Samsvar som standard',
    pageSecuritySec4Desc: 'Fordi HandleMyFile ikke kan få tilgang til filene dine, samsvarer bruken av verktøyene våre automatisk med de strengeste databeskyttelseslovene over hele verden.',
    pageSecuritySec5Title: 'Ikke stol på oss. Bekreft det.',
    pageSecuritySec5Desc: 'Du trenger ikke ta vårt ord for det. Du kan selv bevise vår offline-garanti i tre enkle trinn:',
    pageSecuritySec6Title: 'Fremtiden er lokal',
    pageSecuritySec6Desc: 'Vi ser for oss et nett der hjelpeapper respekterer maskinvaren din og personvernet ditt. Velkommen til den nye æraen med databehandling på klientsiden.',
    footerUseCases: 'Brukssaker',
    pageUseCasesHero: 'Bygget for ethvert yrke',
    pageUseCasesHeroSub: 'Fra strenge juridiske miljøer til kreative byråer, oppdag hvorfor fagfolk stoler på vår behandlingsarkitektur på klientsiden.',
    pageUseCasesBadge: 'Bransjeløsninger',
    pageUseCasesSec2Title: 'Juridisk og advokatfirmaer',
    pageUseCasesSec2Desc: 'Advokater håndterer svært konfidensielle NDAer, kontrakter og rettsdokumenter. Å laste opp disse dokumentene til tilfeldige sky-APIer er en stor forpliktelse. Med HandleMyFile kan juridiske team redigere, slå sammen og dele PDF-saksfiler helt offline, noe som sikrer absolutt klientkonfidensialitet.',
    pageUseCasesSec3Title: 'Human Resources (HR)',
    pageUseCasesSec3Desc: 'HR-avdelinger håndterer PII (Personlig Identifiserbar Informasjon) på daglig basis. Skanning av ID-er, håndtering av lønnsregneark og håndtering av tilbudsbrev krever streng overholdelse av GDPR/CCPA. HandleMyFile lar HR-fagfolk administrere disse filene uten å bryte interne IT-sikkerhetspolicyer.',
    pageUseCasesSec4Title: 'Studenter og utdanning',
    pageUseCasesSec4Desc: 'Studenter skal ikke måtte betale $20/måned bare for å slå sammen gruppeprosjektoppgavene eller komprimere en presentasjon for å passe til universitetsportalens opplastingsgrense på 5MB. HandleMyFile gir ubegrenset tilgang til premiumverktøy gratis, med null filstørrelsesgrenser.',
    pageUseCasesSec5Title: 'Eiendom og meglere',
    pageUseCasesSec5Desc: 'Eiendomsmeglere håndterer massive eiendomsbrosjyrer fullpakket med høyoppløselige bilder som er for store til å sende via e-post til kundene. De må også raskt vannmerke eiendomsplaner og signere leieavtaler. HandleMyFile håndterer 100MB+ filer umiddelbart.',
    pageUseCasesSec6Title: 'Finn din egen brukssak',
    pageUseCasesSec6Desc: 'Uansett bransje, hvis du jobber med dokumenter, er HandleMyFile den sikreste og raskeste måten å få jobben gjort. Prøv hele pakken vår med over 20 verktøy i dag.',
    footerCompare: 'Sammenligne',
    pageCompareHero: 'HandleMyFile vs The Rest',
    pageCompareHeroSub: 'Lei av å vente på at filene skal lastes opp? Frustrert over 5MB filgrenser? Oppdag hvorfor fagfolk bytter til dokumentverktøy på klientsiden.',
    pageCompareBadge: 'Det smarte alternativet',
    pageCompareSec2Title: 'Funksjonssammenligning',
    pageCompareSec3Title: 'Slutt å vente på fremdriftsindikatorer',
    pageCompareSec3Desc: 'Med skyverktøy, hvis du vil slå sammen tre 50 MB PDF-filer, må du laste opp 150 MB data. Vent deretter på at serveren deres skal behandle den. Last deretter ned resultatet på 150 MB. HandleMyFile behandler 150 MB umiddelbart på din lokale disk.',
    pageCompareSec4Title: 'Personvern er ikke en premiumfunksjon',
    pageCompareSec4Desc: 'Konkurrenter ber deg betale $20 i måneden for "Sikker behandling". Vi mener at du ikke trenger å betale løsepenger for å holde dokumentene dine private. Vår offline-arkitektur garanterer personvern som standard, gratis.',
    pageCompareSec5Title: 'Unngå filstørrelsesfellen',
    pageCompareSec5Desc: 'Har du noen gang prøvd å komprimere en PDF, bare for å bli fortalt at filen er "For stor for gratisnivået"? Vi hater kunstige grenser. HandleMyFile bruker enhetens RAM, noe som betyr at du kan behandle 1GB+ filer hvis datamaskinen din kan håndtere det.',
    pageCompareSec6Title: 'Bytt i dag',
    pageCompareSec6Desc: 'Slutt å gå på akkord med hastighet, personvern og kostnader. Bli med tusenvis av fagfolk som allerede har byttet til den raskeste offline dokumentverktøysettet på nettet.',
    footerLanguages: 'Støttede språk',
    pageLangHero: 'Tilgjengelig over hele verden',
    pageLangHeroSub: 'Dokumentverktøy skal være tilgjengelig for alle, uavhengig av hvilket språk du snakker. Vi støtter for øyeblikket 30 lokaliserte versjoner av HandleMyFile.',
    pageLangBadge: 'Global plattform',
    pageLangSec2Title: 'Velg din region',
    pageLangSec3Title: 'Universelt grensesnitt',
    pageLangSec3Desc: 'Hvert verktøy, knapp, feilmelding og veiledning på HandleMyFile har blitt lokalisert. Vi opprettholder en streng oversettelsesmatrise for å sikre at opplevelsen din føles naturlig og intuitiv.',
    pageLangSec4Title: 'Null ventetid, hvor som helst',
    pageLangSec4Desc: 'Fordi HandleMyFile er avhengig av WebAssembly-behandling i stedet for skyservere, spiller det ingen rolle om du er i New York eller Jakarta. Du vil oppleve nøyaktig samme umiddelbare dokumentbehandlingshastigheter uten nettverksforsinkelse.',
    pageLangSec5Title: 'Samfunnsdrevet',
    pageLangSec5Desc: 'Legger du merke til en oversettelse som føles litt dårlig? Vi er avhengige av at vår globale brukerbase hjelper til med å avgrense og perfeksjonere lokaliseringene våre. Kontakt oss for å foreslå forbedringer for ditt morsmål.',
    pageLangSec6Title: 'Klar til å behandle?',
    pageLangSec6Desc: 'Velg et verktøy nedenfor for å komme i gang sikkert og gratis.',
