    zeroUploadDetails: 'На відміну від традиційних хмарних конвертерів, які завантажують ваші приватні документи на віддалені сервери, наша платформа виконує механізми C/C++ WebAssembly безпосередньо в оперативній пам’яті вашого браузера. Ваші конфіденційні документи ніколи не потрапляють в Інтернет.',
