    footerPricing: 'penetapan harga',
    pagePricingHero: 'Sifar Langganan. Had Sifar.',
    pagePricingHeroSub: 'Alat dokumen gred perusahaan biasanya berharga $20/bulan. Kami percaya privasi dan utiliti harus menjadi hak asasi manusia. HandleMyFile adalah percuma sepenuhnya.',
    pagePricingBadge: 'Percuma secara radikal',
    pagePricingComp: 'Alat Awan Tradisional',
    pagePricingSec3Title: 'Bagaimana ini boleh berlaku?',
    pagePricingSec3Desc: 'Alat tradisional mempunyai bil pelayan yang mahal kerana ia memproses fail anda pada awan mereka. Kami mengalihkan enjin C++ dan Rust untuk dijalankan di dalam penyemak imbas anda. Komputer anda melakukan kerja berat, bermakna kos pelayan kami hampir sifar. Kami menyampaikan simpanan tersebut terus kepada anda.',
    pagePricingSec4Title: 'Mampan & Telus',
    pagePricingSec4Desc: 'Untuk memastikan HandleMyFile 100% percuma selama-lamanya, kami bergantung pada iklan yang tidak mengganggu dan analitik web standard. Walau bagaimanapun, privasi anda adalah keutamaan kami. Kami tidak pernah mengimbas, mengekstrak atau menjual kandungan fail anda. Apa yang berlaku dalam editor, kekal dalam editor.',
    pagePricingSec5Title: 'Percuma untuk Kegunaan Perniagaan',
    pagePricingSec5Desc: 'Ya, anda boleh menggunakan HandleMyFile untuk syarikat anda. Malah, seni bina pemprosesan tempatan kami menjadikan kami satu-satunya platform yang cukup selamat untuk persekitaran korporat yang ketat, pasukan undang-undang dan profesional penjagaan kesihatan.',
    pagePricingSec6Title: 'Sokong Projek',
    pagePricingSec6Desc: 'Kami tidak mengenakan bayaran untuk langganan, tetapi memastikan domain dan pembangunan terus hidup memerlukan masa. Jika HandleMyFile menyelamatkan hari anda, pertimbangkan untuk berkongsinya dengan pasukan anda. Dari mulut ke mulut adalah satu-satunya strategi pemasaran kami.',
    shareBtn: 'Kongsi HandleMyFile',
    footerSecurity: 'Keselamatan & Amanah',
    pageSecurityHero: 'Privasi Matematik. Sifar Muat Naik.',
    pageSecurityHeroSub: 'Kebanyakan alat dokumen menjanjikan mereka memadamkan fail anda selepas 1 jam. Kami berjanji kami tidak akan melihat fail anda sejak awal lagi.',
    pageSecurityBadge: 'Pusat Amanah',
    pageSecuritySec2Title: 'Revolusi WebAssembly',
    pageSecuritySec3Title: 'Dokumen Anda Buta Kepada Kami',
    pageSecuritySec3Desc: 'Walaupun kami menggunakan analitis standard untuk meningkatkan pengalaman tapak web kami, skrip kami tidak pernah menyentuh dokumen anda. Kami tidak mengekstrak metadata, kandungan teks atau imej. Kotak pasir pemprosesan dokumen adalah serba lengkap dalam tab penyemak imbas anda.',
    pageSecuritySec4Title: 'Pematuhan secara Lalai',
    pageSecuritySec4Desc: 'Oleh kerana HandleMyFile tidak boleh mengakses fail anda, menggunakan alatan kami secara automatik mematuhi undang-undang perlindungan data yang paling ketat di seluruh dunia.',
    pageSecuritySec5Title: 'Jangan Percaya Kami. Sahkan Ia.',
    pageSecuritySec5Desc: 'Anda tidak perlu mengambil kata-kata kami untuk itu. Anda boleh membuktikan sendiri jaminan luar talian kami dalam 3 langkah mudah:',
    pageSecuritySec6Title: 'Masa Depan adalah Tempatan',
    pageSecuritySec6Desc: 'Kami membayangkan web di mana apl utiliti menghormati perkakasan anda dan privasi anda. Selamat datang ke era baharu pengkomputeran pihak pelanggan.',
    footerUseCases: 'Kes Penggunaan',
    pageUseCasesHero: 'Dibina untuk Setiap Profesion',
    pageUseCasesHeroSub: 'Daripada persekitaran undang-undang yang ketat kepada agensi kreatif, temui sebab profesional mempercayai seni bina pemprosesan sebelah pelanggan kami.',
    pageUseCasesBadge: 'Penyelesaian Industri',
    pageUseCasesSec2Title: 'Undang-undang & Firma Guaman',
    pageUseCasesSec2Desc: 'Peguam mengendalikan NDA, kontrak dan pemfailan mahkamah yang sangat sulit. Memuat naik dokumen ini ke API awan rawak adalah liabiliti utama. Dengan HandleMyFile, pasukan undang-undang boleh menyunting, menggabungkan dan memisahkan fail kes PDF sepenuhnya di luar talian, memastikan kerahsiaan pelanggan mutlak.',
    pageUseCasesSec3Title: 'Sumber Manusia (HR)',
    pageUseCasesSec3Desc: 'Jabatan HR berurusan dengan PII (Maklumat Pengenalan Peribadi) setiap hari. Mengimbas ID, mengendalikan hamparan gaji dan mengurus surat tawaran memerlukan pematuhan GDPR/CCPA yang ketat. HandleMyFile membolehkan profesional HR mengurus fail ini tanpa melanggar dasar keselamatan IT dalaman.',
    pageUseCasesSec4Title: 'Pelajar & Pendidikan',
    pageUseCasesSec4Desc: 'Pelajar tidak sepatutnya membayar $20/bulan hanya untuk menggabungkan tugasan projek kumpulan mereka atau memampatkan pembentangan agar memenuhi had muat naik portal universiti 5MB. HandleMyFile menyediakan akses tanpa had kepada alatan premium secara percuma, dengan had saiz fail sifar.',
    pageUseCasesSec5Title: 'Hartanah & Ejen',
    pageUseCasesSec5Desc: 'Ejen hartanah mengendalikan risalah hartanah besar-besaran yang penuh dengan imej resolusi tinggi yang terlalu besar untuk dihantar melalui e-mel kepada pelanggan. Mereka juga perlu menanda air pelan hartanah dan menandatangani perjanjian pajakan dengan cepat. HandleMyFile mengendalikan 100MB+ fail serta-merta.',
    pageUseCasesSec6Title: 'Cari Kes Penggunaan Anda Sendiri',
    pageUseCasesSec6Desc: 'Tidak kira industri anda, jika anda bekerja dengan dokumen, HandleMyFile ialah cara paling selamat dan terpantas untuk menyelesaikan kerja. Cuba suite penuh kami yang mengandungi 20+ alatan hari ini.',
    footerCompare: 'Bandingkan',
    pageCompareHero: 'HandleMyFile vs The Rest',
    pageCompareHeroSub: 'Bosan menunggu fail untuk dimuat naik? Kecewa dengan had fail 5MB? Temui sebab profesional beralih kepada alat dokumen pihak pelanggan.',
    pageCompareBadge: 'Alternatif Pintar',
    pageCompareSec2Title: 'Perbandingan Ciri',
    pageCompareSec3Title: 'Berhenti Menunggu pada Bar Kemajuan',
    pageCompareSec3Desc: 'Dengan alatan awan, jika anda ingin menggabungkan tiga PDF 50MB, anda perlu memuat naik 150MB data. Kemudian tunggu pelayan mereka memprosesnya. Kemudian muat turun hasil 150MB. HandleMyFile memproses 150MB serta-merta pada cakera tempatan anda.',
    pageCompareSec4Title: 'Privasi Bukan Ciri Premium',
    pageCompareSec4Desc: 'Pesaing meminta anda membayar $20 sebulan untuk "Pemprosesan Selamat". Kami percaya anda tidak perlu membayar wang tebusan untuk merahsiakan dokumen anda. Seni bina luar talian kami menjamin privasi secara lalai, secara percuma.',
    pageCompareSec5Title: 'Melarikan diri daripada Perangkap Saiz Fail',
    pageCompareSec5Desc: 'Pernahkah anda cuba memampatkan PDF, hanya untuk diberitahu bahawa fail itu "Terlalu besar untuk peringkat percuma"? Kami benci had buatan. HandleMyFile menggunakan RAM peranti anda, bermakna anda boleh memproses fail 1GB+ jika komputer anda boleh mengendalikannya.',
    pageCompareSec6Title: 'Buat Tukar Hari Ini',
    pageCompareSec6Desc: 'Berhenti berkompromi pada kelajuan, privasi dan kos. Sertai beribu-ribu profesional yang telah bertukar kepada kit alat dokumen luar talian terpantas di web.',
    footerLanguages: 'Bahasa yang Disokong',
    pageLangHero: 'Tersedia Di Seluruh Dunia',
    pageLangHeroSub: 'Utiliti dokumen harus boleh diakses oleh semua orang, tidak kira apa bahasa yang anda gunakan. Pada masa ini kami menyokong 30 versi setempat HandleMyFile.',
    pageLangBadge: 'Platform Global',
    pageLangSec2Title: 'Pilih Wilayah Anda',
    pageLangSec3Title: 'Antara Muka Universal',
    pageLangSec3Desc: 'Setiap alat, butang, mesej ralat dan panduan pada HandleMyFile telah disetempatkan. Kami mengekalkan matriks terjemahan yang ketat untuk memastikan pengalaman anda berasa asli dan intuitif.',
    pageLangSec4Title: 'Kependaman Sifar, Di Mana-mana',
    pageLangSec4Desc: 'Oleh kerana HandleMyFile bergantung pada pemprosesan WebAssembly dan bukannya pelayan awan, tidak kira anda berada di New York atau Jakarta. Anda akan mengalami kelajuan pemprosesan dokumen segera yang sama tanpa kependaman rangkaian.',
    pageLangSec5Title: 'Didorong Komuniti',
    pageLangSec5Desc: 'Perhatikan terjemahan yang terasa sedikit tidak jelas? Kami bergantung pada pangkalan pengguna global kami untuk membantu memperhalusi dan menyempurnakan penyetempatan kami. Hubungi kami untuk mencadangkan penambahbaikan untuk bahasa ibunda anda.',
